/* DAWAH X — ahmad, অধ্যায় 59 · খণ্ড 59 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][59]=[[11601,11601,"","আমরা বাবার ছেলেকে বলেছিলাম, ঈশ্বর একজন মাস্টারের কাছে এসেছেন।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى لَا يُقَالَ فِي الْأَرْضِ اللَّهُ اللَّهُ ‏","","",""],[11602,11602,"","আমরা আমার বাবার ছেলেকে বলছি মানুষকে রক্ষা করার জন্য তিনি আমাকে কিছু একটা করতে বলেছেন। যদি আপনি না বলেন, ঈশ্বরের কাছে হয়ত আল্লাহ্‌র অনুগ্রহ আছে, আমি নই। আমি এটা পড়তে চাই, আর বলতে চাই, এটা ভালো দিন। ঈশ্বরের কাছে বলতে হবে আমরা ঈশ্বরের অনুগ্রহের মাধ্যমে এসেছি, ইশ্বর তার ত্রুটির উপর রেগে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسْأَلُونِي عَنْ شَيْءٍ إِلَى يَوْمِ الْقِيَامَةِ إِلَّا حَدَّثْتُكُمْ قَالَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ حُذَافَةَ ‏ ‏يَا رَسُولَ اللَّهِ مَنْ أَبِي قَالَ أَبُوكَ ‏ ‏حُذَافَةُ ‏ ‏فَقَالَتْ أُمُّهُ مَا أَرَدْتَ إِلَى هَذَا قَالَ أَرَدْتُ أَنْ أَسْتَرِيحَ قَالَ وَكَانَ يُقَالُ فِيهِ ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏وَأَحْسَبُ هَذَا عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِينَا بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيًّا نَعُوذُ بِاللَّهِ مِنْ غَضِبِ اللَّهِ وَغَضِبِ رَسُولِهِ ‏","","",""],[11603,11603,"","আমরা বাবার ছেলেকে বলছি যারা কখনো তার জন্য ঈশ্বরকে করেনি, আদালত হল রেখার রেখা এবং আপনাদের ছেলেদের দ্বারা আপনারা নির্যাতন করছেন।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ مَا تَدَاوَيْتُمْ بِهِ ‏ ‏الْحِجَامَةُ ‏ ‏وَالْقُسْطُ ‏ ‏الْبَحْرِيُّ وَلَا تُعَذِّبُوا صِبْيَانَكُمْ ‏ ‏بِالْغَمْزِ ‏","","",""],[11604,11604,"","আমরা বাবার ছেলেকে বলেছিলাম ঘোড়ার কথা, যারা বলেছে খোদা এটা দেয়ালের মধ্যে দিয়ে বানিয়েছে, আমি একটু দূরে আছি, তোমার ঈর্ষার কারণে, আমি তোমার থেকে ঈর্ষার ভয়ে আছি, আমি যাই। ঈশ্বরের অনুগ্রহের উপর.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَإِذَا أَنَا بِقَصْرٍ مِنْ ذَهَبٍ فَقُلْتُ لِمَنْ هَذَا الْقَصْرُ قَالُوا لِشَابٍّ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏قُلْتُ لِمَنْ قَالُوا ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَالَ فَلَوْلَا مَا عَلِمْتُ مِنْ غَيْرَتِكَ لَدَخَلْتُهُ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏عَلَيْكَ يَا رَسُولَ اللَّهِ أَغَارُ ‏","","",""],[11605,11605,"","আমরা বাবার ছেলেকে একটা ঘোড়ার কথা বলেছি, যে বলেছে খোদা ঈশ্বরের দোহাই দিয়ে রক্ষা করেছে। আমি আল্লাহকে পছন্দ করি তার সাথে দেখা করতে আর যে ঈশ্বরকে ঘৃণা করে তাকে বলতে যে ঈশ্বরই নরক। কিন্তু ক্ষমতার অভাব হচ্ছে যে সে বিখ্যাত হয়েছে... ...আর তার সাথে যা আছে, তার সাথে কিছু করার আছে, ঈশ্বর ঈশ্বরকে তার সাথে দেখা করতে বা মহান রাজা হতে চান না। তাকে আসতে বলা হয়েছে, খারাপ মানুষ ভাবলো এটা ঈশ্বরের দোহাই আর তার মিটিংকে ঘৃণা করে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ قُلْنَا يَا رَسُولَ اللَّهِ كُلُّنَا نَكْرَهُ الْمَوْتَ قَالَ لَيْسَ ذَاكَ كَرَاهِيَةَ الْمَوْتِ وَلَكِنَّ الْمُؤْمِنَ إِذَا حُضِرَ جَاءَهُ الْبَشِيرُ مِنْ اللَّهِ عَزَّ وَجَلَّ بِمَا هُوَ ‏ ‏صَائِرٌ ‏ ‏إِلَيْهِ فَلَيْسَ شَيْءٌ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَكُونَ قَدْ لَقِيَ اللَّهَ عَزَّ وَجَلَّ فَأَحَبَّ اللَّهُ لِقَاءَهُ وَإِنَّ الْفَاجِرَ أَوْ الْكَافِرَ إِذَا حُضِرَ جَاءَهُ بِمَا هُوَ ‏ ‏صَائِرٌ ‏ ‏إِلَيْهِ مِنْ الشَّرِّ ‏ ‏أَوْ مَا يَلْقَاهُ مِنْ الشَّرِّ ‏ ‏فَكَرِهَ لِقَاءَ اللَّهِ وَكَرِهَ اللَّهُ لِقَاءَهُ ‏","","",""],[11606,11606,"","আমরা বাবার ছেলের সাথে কথা বলেছি তিনি বলেছিলেন তিনি আপনার টাকা ভুলে গেছেন। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আত্মসমর্পণ করেছেন এবং আমি ঈশ্বরের অনুগ্রহ থেকে একটি রাজকীয় স্বপ্ন দেখি নি। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏مَا مَسِسْتُ شَيْئًا قَطُّ خَزًّا وَلَا حَرِيرًا أَلْيَنَ مِنْ كَفِّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا شَمَمْتُ رَائِحَةً أَطْيَبَ مِنْ رِيحِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11607,11607,"","আমরা বাবার ছেলেকে বলেছিলাম যে ঘোড়া আর ভগবান আমার সাথে দেখা করে... ...আমাদের দেখা মহান মূল্য নিয়ে। ঈশ্বর তার জন্য প্রার্থনা করেছেন আর একজন মানুষকে আত্মসমর্পণ করেছেন যেন সে শান্তিতে আছে। তার আত্মা ছিল তার আত্মার. আমি আপনাকে কল দেব অথবা সে যা বলেছে তা জিজ্ঞেস করব. ঈশ্বরের দোহাই এটা করেছে এবং সৃষ্টিকর্তাকে আত্মসমর্পণ করবে এটা শেষ সুযোগ হবে না. একজন, আমরা আগুনটা ব্যবহার করেছি, বলেছেন, \"ঈশ্বর জিতেছে এবং আল্লাহ্‌কে খুঁজে পেয়েছে, শক্তিশালী হয়েছে এবং আঘাত করেছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ بَكْرٍ السَّهْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَادَ رَجُلًا مِنْ الْمُسْلِمِينَ قَدْ صَارَ مِثْلَ الْفَرْخِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ كُنْتَ تَدْعُو بِشَيْءٍ أَوْ تَسْأَلُهُ إِيَّاهُ قَالَ نَعَمْ كُنْتُ أَقُولُ اللَّهُمَّ مَا كُنْتَ مُعَاقِبِي بِهِ فِي الْآخِرَةِ فَعَجِّلْهُ لِي فِي الدُّنْيَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبْحَانَ اللَّهِ لَا تُطِيقُهُ وَلَا تَسْتَطِيعُهُ فَهَلَّا قُلْتَ ‏ ‏اللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ قَالَ فَدَعَا اللَّهَ عَزَّ وَجَلَّ فَشَفَاهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[11608,11608,"","আমরা বাবার ছেলের সাথে কথা বলেছি... ...মানুষদের জন্য সে বলেছে সে লর্ডের কাছে সাহায্য করেছে, সে মোটা হয়ে গেছে, যদি সে মোটা হতে চায় আর সে মোটা হয়ে যায় মোটা হতে ভালবাসে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ الرَّجُلُ يَأْتِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيُسْلِمُ لِشَيْءٍ ‏ ‏يُعْطَاهُ مِنْ الدُّنْيَا فَلَا يُمْسِي حَتَّى يَكُونَ الْإِسْلَامُ أَحَبَّ إِلَيْهِ وَأَعَزَّ عَلَيْهِ مِنْ الدُّنْيَا وَمَا فِيهَا ‏","","",""],[11609,11609,"","আমি আমার বাবার ছেলেকে বলেছিলাম, আমাকে ভুলে গিয়ে সে আমাকে কিছু একটা করতে চায়। আমি নিজেই তার উপর ছেড়ে দেব।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكُنْ يُسْأَلُ شَيْئًا عَلَى الْإِسْلَامِ إِلَّا أَعْطَاهُ قَالَ فَأَتَاهُ رَجُلٌ فَسَأَلَهُ فَأَمَرَ لَهُ بِشَاءٍ كَثِيرٍ بَيْنَ جَبَلَيْنِ مِنْ شَاءِ ‏ ‏الصَّدَقَةِ ‏ ‏قَالَ فَرَجَعَ إِلَى قَوْمِهِ فَقَالَ يَا قَوْمِ أَسْلِمُوا فَإِنَّ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْطِي عَطَاءً مَا ‏ ‏يَخْشَى ‏ ‏الْفَاقَةَ ‏","","",""],[11610,11610,"","ঈশ্বর তাকে আদেশ দিয়েছেন এবং শীঘ্রই তার উদ্দেশ্য পূর্ণ করার জন্য আমি তাঁকে খুঁজে পাব না । তাকে আবার ক্ষমা করে দেওয়া হয়েছে, আর সে তার বাসায় ফিরে এসেছে, আর সে তার মৃতনেত্রীকে খুন করার জন্য নিঃশব্দে তাকে খুন করে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏بَعَثَتْ مَعِي ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏بِمِكْتَلٍ ‏ ‏فِيهِ رُطَبٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ أَجِدْهُ وَخَرَجَ قَرِيبًا إِلَى مَوْلًى لَهُ دَعَاهُ صَنَعَ لَهُ طَعَامًا قَالَ فَأَتَيْتُهُ فَإِذَا هُوَ يَأْكُلُ فَدَعَانِي لِآكُلَ مَعَهُ قَالَ وَصَنَعَ لَهُ ‏ ‏ثَرِيدًا ‏ ‏بِلَحْمٍ وَقَرْعٍ قَالَ ‏ ‏وَإِذَا هُوَ يُعْجِبُهُ الْقَرْعُ قَالَ فَجَعَلْتُ أَجْمَعُهُ ‏ ‏وَأُدْنِيهِ مِنْهُ قَالَ فَلَمَّا ‏ ‏طَعِمَ ‏ ‏رَجَعَ إِلَى مَنْزِلِهِ قَالَ وَوَضَعْتُ ‏ ‏الْمِكْتَلَ ‏ ‏بَيْنَ يَدَيْهِ قَالَ فَجَعَلَ يَأْكُلُ وَيَقْسِمُ حَتَّى فَرَغَ مِنْ آخِرِهِ ‏","","",""],[11611,11611,"","আমরা বাবার ছেলের সাথে কথা বলেছি, যারা ঈশ্বরের পতাকায় গিয়েছিল এবং তার শান্তির জন্য প্রার্থনা করেছিল। সে এক সময় পার হয়ে যায় এবং এক বছর বয়সী ছিল যে তারা ছিল বলে তারা ছিল। আর সে তোমার দাস, তোমার দাসগণ বলল, সে যেন অন্য কোন কালের জন্য বাইরে যায়, আমাকে না বলে । আমি তাকে বলেছিলাম যে, তাকে যেন তার হৃদয় থেকে পর্দার আড়ালে কবর দেওয়া হয় ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏فَأَتَتْهُ بِتَمْرٍ وَسَمْنٍ وَكَانَ صَائِمًا فَقَالَ ‏ ‏أَعِيدُوا تَمْرَكُمْ فِي وِعَائِهِ وَسَمْنَكُمْ فِي ‏ ‏سِقَائِهِ ‏ ‏ثُمَّ قَامَ إِلَى نَاحِيَةِ الْبَيْتِ فَصَلَّى رَكْعَتَيْنِ وَصَلَّيْنَا مَعَهُ ثُمَّ دَعَا ‏ ‏لِأُمِّ سُلَيْمٍ ‏ ‏وَلِأَهْلِهَا بِخَيْرٍ فَقَالَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ لِي ‏ ‏خُوَيْصَّةً ‏ ‏قَالَ وَمَا هِيَ قَالَتْ خَادِمُكَ ‏ ‏أَنَسٌ ‏ ‏قَالَ فَمَا تَرَكَ خَيْرَ آخِرَةٍ وَلَا دُنْيَا إِلَّا دَعَا لِي بِهِ وَقَالَ اللَّهُمَّ ارْزُقْهُ مَالًا وَوَلَدًا وَبَارِكْ لَهُ فِيهِ قَالَ فَمَا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِنْسَانٌ أَكْثَرُ مِنِّي مَالًا وَذَكَرَ أَنَّهُ لَا يَمْلِكُ ذَهَبًا وَلَا فِضَّةً غَيْرَ خَاتَمِهِ قَالَ وَذَكَرَ أَنَّ ابْنَتَهُ الْكُبْرَى ‏ ‏أُمَيْنَةَ ‏ ‏أَخْبَرَتْهُ أَنَّهُ دُفِنَ مِنْ ‏ ‏صُلْبِهِ ‏ ‏إِلَى مَقْدَمِ ‏ ‏الْحَجَّاجِ ‏ ‏نَيِّفًا عَلَى عِشْرِينَ وَمِائَةٍ ‏","","",""],[11612,11612,"","আমরা বাবার ছেলের সাথে কথা বলেছি, তিনি বলেছিলেন যে তিনি যদি এটা চান তাহলে তিনি এটা জিজ্ঞাসা করতেন, তিনি যুবকদের দেখতেন না, যেমন তিনি তার দশ অথবা দশ বার করতে পারতেন। আমি আমার বাবার ছেলের ছেলের সাথে কথা বলেছি। আমি তাকে বললাম যে তিনি যদি তিনি এটা জিজ্ঞেস করতেন, \"তুমি\" এবং \"আমি জানি না।\" সে শুধু ঘৃণা করে... ...কিন্তু সে আমার বাবাকে অনেক ঘৃণা করে... ...আর সে একটা লজ্জা পায়.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏هَلْ ‏ ‏خَضَبَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهُ لَمْ يَرَ مِنْ الشَّيْبِ إِلَّا نَحْوًا مِنْ سَبْعَ عَشْرَةَ أَوْ عِشْرِينَ شَعْرَةً فِي مُقَدَّمِ لِحْيَتِهِ وَقَالَ إِنَّهُ لَمْ يَشِنْ بِالشَّيْبِ ‏ ‏فَقِيلَ ‏ ‏لِأَنَسٍ ‏ ‏أَشَيْنٌ هُوَ قَالَ كُلُّكُمْ يَكْرَهُهُ وَلَكِنْ ‏ ‏خَضَبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِالْحِنَّاءِ وَالْكَتَمِ ‏ ‏وَخَضَبَ ‏ ‏عُمَرُ ‏ ‏بِالْحِنَّاءِ ‏","","",""],[11613,11613,"","আমরা বাবার ছেলেকে কথা বলেছি... ...মানুষদের ঘোড়ার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِهِ فَاطَّلَعَ إِلَيْهِ ‏ ‏رَجُلٌ ‏ ‏فَأَهْوَى ‏ ‏إِلَيْهِ ‏ ‏بِمِشْقَصٍ ‏ ‏مَعَهُ ‏ ‏فَتَأَخَّرَ ‏ ‏الرَّجُلُ ‏","","",""],[11614,11614,"","আমরা বাবার ছেলেকে বলেছিলাম, ওকে বাঁচানোর জন্য বাবার সাথে ওর বাবার সম্পর্ক ছিলো। তার থেকে সে তোমাকে ঈশ্বরের কাছে বলে দিয়েছে, যখন সে তাকে মারতে চায়, সে তোমাকে ধরে রাখতে পারবে না। \"ঈশ্বর, আমি এটা করবো না\" কসম করে বলছি, ঈশ্বরের কসম কেটে বলছি,","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى ‏ ‏اسْتَحْمَلَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَافَقَ مِنْهُ شُغْلًا فَقَالَ وَاللَّهِ لَا أَحْمِلُكَ فَلَمَّا ‏ ‏قَفَّى ‏ ‏دَعَاهُ ‏ ‏فَحَمَلَهُ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّكَ حَلَفْتَ أَنْ تَحْمِلَنِي قَالَ ‏ ‏فَأَنَا أَحْلِفُ لَأَحْمِلَنَّكَ ‏","","",""],[11615,11615,"","আমরা আমার বাবার ছেলের সাথে কথা বলেছি, ঈশ্বরের নিজের শান্তি নিশ্চিত করার স্বপ্নের কথা, তার প্রতিদ্বন্দ্বীরা হলো শপথ-নেতা, প্রভু, আমি আপনাকে তিনটা বিশেষ ঘটনা জিজ্ঞাসা করবো যা না। তাকে শিক্ষা দেওয়া, তিনি যে জিনিসটা খায় তা হলো পাগল এবং লর্ড তার বাবার মত। আমি বলছি, তারা এখন ঘুমাতে যাচ্ছে এবং বলে যে তুমি অন্ধকার থেকে মুক্ত ক্ষমতা অথবা সবচাইতে খারাপ, আগুন থেকে বের হয়ে আসে, যেন মানুষ এটাকে উড়িয়ে দিয়ে সেটা খেয়ে ফেলে বা খাওয়ার জন্য যাই হোক না কেন, তার বাবা আর তার মায়েরও আছে, ঈশ্বরের দয়া, তাঁর জন্ম এবং তাঁর জীবনের উপর, তিনি আমাকে বলেছিলেন আমি ঈশ্বর না বলতে চাই আপনি বলেছিলেন যে আপনি বলতেন, ঈশ্বরই হবে ঈশ্বরের ইচ্ছা, তারা জানে আমার নাম গভীর। আমার সাথে আপনি তাদের বলবেন আমি কি হবে হবে, ঈশ্বর হয়ত বলেন যে তারা ভাল এবং ভাল আছে আমার ছেলে, আপনি একটি ছেড়ে দিতে হবে আমি নিশ্চিত সে এটা ছেড়ে দেবে না। তারা বলেছিল, আমরা বিরক্ত হয়ে গেছি এবং আমরা আমাদের সন্তান ছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ سَلَامٍ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقْدَمَهُ ‏ ‏الْمَدِينَةَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي سَائِلُكَ عَنْ ثَلَاثِ خِصَالٍ لَا يَعْلَمُهُنَّ إِلَّا نَبِيٌّ قَالَ سَلْ قَالَ مَا أَوَّلُ ‏ ‏أَشْرَاطِ ‏ ‏السَّاعَةِ وَمَا أَوَّلُ مَا يَأْكُلُ مِنْهُ أَهْلُ الْجَنَّةِ وَمِنْ أَيْنَ يُشْبِهُ الْوَلَدُ أَبَاهُ وَأُمَّهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَنِي بِهِنَّ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏آنِفًا قَالَ ذَلِكَ عَدُوُّ ‏ ‏الْيَهُودِ ‏ ‏مِنْ الْمَلَائِكَةِ قَالَ أَمَّا أَوَّلُ ‏ ‏أَشْرَاطِ ‏ ‏السَّاعَةِ ‏ ‏فَنَارٌ تَخْرُجُ مِنْ الْمَشْرِقِ فَتَحْشُرُ النَّاسَ إِلَى الْمَغْرِبِ وَأَمَّا أَوَّلُ مَا يَأْكُلُ مِنْهُ أَهْلُ الْجَنَّةِ زِيَادَةُ كَبِدِ حُوتٍ وَأَمَّا شَبَهُ الْوَلَدِ أَبَاهُ وَأُمَّهُ فَإِذَا سَبَقَ مَاءُ الرَّجُلِ مَاءَ الْمَرْأَةِ ‏ ‏نَزَعَ ‏ ‏إِلَيْهِ الْوَلَدُ وَإِذَا سَبَقَ ‏ ‏مَاءُ ‏ ‏الْمَرْأَةِ ‏ ‏مَاءَ ‏ ‏الرَّجُلِ ‏ ‏نَزَعَ ‏ ‏إِلَيْهَا قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّكَ رَسُولُ اللَّهِ وَقَالَ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏الْيَهُودَ ‏ ‏قَوْمٌ ‏ ‏بُهْتٌ ‏ ‏وَإِنَّهُمْ إِنْ يَعْلَمُوا بِإِسْلَامِي يَبْهَتُونِي عِنْدَكَ فَأَرْسِلْ إِلَيْهِمْ فَاسْأَلْهُمْ عَنِّي أَيُّ رَجُلٍ ‏ ‏ابْنُ سَلَامٍ ‏ ‏فِيكُمْ قَالَ فَأَرْسَلَ إِلَيْهِمْ فَقَالَ أَيُّ رَجُلٍ ‏ ‏عَبْدُ اللَّهِ بْنُ سَلَامٍ ‏ ‏فِيكُمْ قَالُوا خَيْرُنَا وَابْنُ خَيْرِنَا وَعَالِمُنَا وَابْنُ عَالِمِنَا وَأَفْقَهُنَا وَابْنُ أَفْقَهِنَا قَالَ أَرَأَيْتُمْ إِنْ أَسْلَمَ تُسْلِمُونَ قَالُوا أَعَاذَهُ اللَّهُ مِنْ ذَلِكَ قَالَ فَخَرَجَ ‏ ‏ابْنُ سَلَامٍ ‏ ‏فَقَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ قَالُوا شَرُّنَا وَابْنُ شَرِّنَا وَجَاهِلُنَا وَابْنُ جَاهِلِنَا فَقَالَ ‏ ‏ابْنُ سَلَامٍ ‏ ‏هَذَا الَّذِي كُنْتُ أَتَخَوَّفُ مِنْهُ ‏","","",""],[11616,11616,"","আমরা বাবার ছেলেকে একটা হাত ধরে কথা বলেছি, যারা বলেছে, কেন সে স্বপ্নের বিষ খায়, স্বপ্নের স্বপ্নের স্বপ্ন দেখে। ঈশ্বর যে ঈশ্বরকে হত্যা করতে চান, তা ঈশ্বরও হত্যা করতে চান। তিনি বলেছিলেন যে, যদি তিনি আমাকে এটা করতে বলেন, তা হলে তিনি বলেছিলেন যে, এটা যদি আমার নিজের একটা স্বপ্ন হতো, তা হলে তিনি বলেছিলেন, তিনি একটা মুক্ত প্রাণী ছিলেন, প্রভু। আমি তাকে বলেছিলাম, আমি জানি, আমি জানি না যে, আমি যদি আমার বাবা আমাকে ছেড়ে দেয়, তাহলে আমি তাকে একটা জিনিস দিতে পারি। কিন্তু আমি জানি না যে, আমি জানি না কেন, আমি যদি আমি এটা একটা জিনিস করতে চাই। কিন্তু আমি জানি, আমি জানি, আমি যদি আমি সত্যিই জানি যে, আমি সত্যিই ছোট ছিলাম। কিন্তু আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি যা কিছু করি, তা হলে আমি জানি না । তুমি বলছ আমার মা স্বপ্নের মধ্যে আমার ছেলেকে খুন করার চেষ্টা করেছে। ঈশ্বরের দোহাই দিয়ে তোমার টাকা ভুলে যাওয়ার পথে... ...আমি বলেছিলাম যে, আমি উদ্ধার করতে চাই। আমি আপনাকে যা বলতে চাই তা করতে বলি। আমি যা বলি, তা হলো আমি যা বলি তা হলো, যা বলি তা আমি বলি অথবা যা বলি না তা আমার কাছে সবচেয়ে বিখ্যাত। কর.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا انْهَزَمَ الْمُسْلِمُونَ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏نَادَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏يَا رَسُولَ اللَّهِ اقْتُلْ مَنْ بَعْدَنَا انْهَزَمُوا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ كَفَى قَالَ فَأَتَاهَا ‏ ‏أَبُو طَلْحَةَ ‏ ‏وَمَعَهَا ‏ ‏مِعْوَلٌ ‏ ‏فَقَالَ مَا هَذَا يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏قَالَتْ إِنْ دَنَا مِنِّي أَحَدٌ مِنْ الْمُشْرِكِينَ بَعَجْتُهُ قَالَ فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَا رَسُولَ اللَّهِ انْظُرْ مَا تَقُولُ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏قَالَ ‏ ‏لَمَّا أَرَدْتُ أَنْ أُسْلِمَ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنِّي سَائِلُكَ فَقَالَ سَلْ عَمَّا بَدَا لَكَ قَالَ قُلْتُ مَا أَوَّلُ مَا يَأْكُلُ أَهْلُ الْجَنَّةِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[11617,11617,"","আমরা বাবার ছেলের সাথে আমার এক হাত কথা বলেছি এবং সে বলে আমরা ভালো আছি, যারা বলে আমি গানের সাথে খেলছি। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করবেন। আমি যে সকল বার্তাবাহককে সমর্পণ করিয়াছি, তাহারা তাঁহার প্রতি যাহা যাহা করিয়াছে, তাহা আমি আর কখনও করিতে পারিব না । তিনি বলেছিলেন, “আমি যখন তাকে বলেছিলাম যে, আমি তার সঙ্গে কথা বলছি, তখন তিনি আমাকে বলেছিলেন যে, আমি তার সঙ্গে কথা বলতে চাই ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَلْعَبُ مَعَ الْغِلْمَانِ فَأَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فِي حَدِيثِهِ عَلَيْنَا ‏ ‏وَأَخَذَ بِيَدِي ‏ ‏فَبَعَثَنِي فِي حَاجَةٍ وَقَعَدَ فِي ظِلِّ ‏ ‏حَائِطٍ ‏ ‏أَوْ جِدَارٍ حَتَّى رَجَعْتُ إِلَيْهِ فَبَلَّغْتُ الرِّسَالَةَ الَّتِي بَعَثَنِي فِيهَا فَلَمَّا أَتَيْتُ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏قَالَتْ مَا حَبَسَكَ قُلْتُ بَعَثَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ لَهُ قَالَتْ وَمَا هِيَ قُلْتُ سِرٌّ قَالَتْ احْفَظْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِرَّهُ قَالَ فَمَا حَدَّثْتُ بِهِ أَحَدًا بَعْدُ ‏","","",""],[11618,11618,"","আমরা বাবার ছেলেকে বলেছিলাম, ঈশ্বরের কাছে ঘোড়ার কথা ভুলে গিয়ে তাকে ছেড়ে দিতে। সে আমাকে এটা করতে বলে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِرَجُلٍ أَسْلِمْ قَالَ أَجِدُنِي كَارِهًا قَالَ ‏ ‏أَسْلِمْ وَإِنْ كُنْتَ كَارِهًا ‏","","",""],[11619,11619,"","আমরা বাবার ছেলেকে সুখী আর আবেগীভাবে বলেছিলাম যে আমরা তার নিজের শাসনে খুশি হব। ঈশ্বর তার জন্য প্রার্থনা করেন আর আমি একটা পরিকল্পনা করে তার কাছে পৌঁছে দেই যা আমি রক্ষা করেছি। তাকে কবর দেওয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏النُّخَاعَةُ ‏ ‏فِي الْمَسْجِدِ خَطِيئَةٌ وَكَفَّارَتُهَا دَفْنُهَا ‏","","",""],[11620,11620,"","আমি যদি ঈশ্বরের সেবায় নিয়োজিত থাকি, তাহলে আমার বাবার ছেলের সাথে আমরা সুখী এবং আবেগপূর্ণভাবে আমাদের মন পরিবর্তন করে দিলাম। তার মাকে নিয়ে পালিয়ে যেতে সে আর মারা যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي الصَّلَاةِ فَإِنَّهُ مُنَاجٍ رَبَّهُ فَلَا يَتْفُلَنَّ أَحَدٌ مِنْكُمْ عَنْ يَمِينِهِ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فَلَا ‏ ‏يَتْفُلُ ‏ ‏أَمَامَهُ وَلَا عَنْ يَمِينِهِ ‏ ‏وَلَكِنْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمَيْهِ ‏","","",""],[11621,11621,"","আমরা বাবার ছেলেকে বলেছিলাম জঙ্গলের সুখময় ছেলে সম্পর্কে, যখন আমরা তাকে সাহায্য করতে পারব, তখন আমি খুশি হব কিভাবে তাকে সাহায্য করতে পারব। তার প্রার্থনা আর সেল্ম আছে আমি শপথ নিতে যাচ্ছি। তারা ঈশ্বরের দোহাই এবং সিনেমা হচ্ছে দুই-সাত-সাত-িক্স-৬ জন-চয়মিস্ট। তার জন্য এক মাস সময় তিনি এই যন্ত্রণা ও অপমানের জন্য প্রার্থনা করেছিলেন । তারা আমাদের বলেছে আমরা দাড়িয়ে আছি আর তারপর তুমি বড় হয়ে গেছো.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏أَتَاهُ ‏ ‏رِعْلٌ ‏ ‏وَذَكْوَانُ ‏ ‏وَعُصَيَّةُ ‏ ‏وَبَنُو لِحْيَانَ ‏ ‏فَزَعَمُوا أَنَّهُمْ قَدْ أَسْلَمُوا فَاسْتَمَدُّوهُ عَلَى قَوْمِهِمْ فَأَمَدَّهُمْ نَبِيُّ اللَّهِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏يَوْمَئِذٍ بِسَبْعِينَ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏كُنَّا نُسَمِّيهِمْ فِي زَمَانِهِمْ الْقُرَّاءَ كَانُوا يَحْطِبُونَ بِالنَّهَارِ وَيُصَلُّونَ بِاللَّيْلِ فَانْطَلَقُوا بِهِمْ حَتَّى إِذَا أَتَوْا ‏ ‏بِئْرَ مَعُونَةَ ‏ ‏غَدَرُوا بِهِمْ فَقَتَلُوهُمْ ‏ ‏فَقَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا فِي صَلَاةِ الصُّبْحِ يَدْعُو عَلَى هَذِهِ الْأَحْيَاءِ ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَعُصَيَّةَ ‏ ‏وَبَنِي لِحْيَانَ ‏ ‏قَالَ قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَحَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏أَنَّهُمْ قَرَءُوا بِهِ قُرْآنًا ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فِي حَدِيثِهِ إِنَّا قَرَأْنَا بِهِمْ قُرْآنًا ‏ ‏بَلِّغُوا عَنَّا قَوْمَنَا وَإِنَّا قَدْ لَقِينَا رَبَّنَا فَرَضِيَ عَنَّا وَأَرْضَانَا ثُمَّ رُفِعَ ذَلِكَ بَعْدُ ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏ثُمَّ ‏ ‏نُسِخَ ‏ ‏ذَلِكَ ‏ ‏أَوْ رُفِعَ ‏","","",""],[11622,11622,"","আমরা বাবার ছেলেকে খুশি আর খুশি হবার কয়েক বছর পর ভয় পেয়ে কথা বলেছি, আমি ঈশ্বরের কাছে বলছি তারা আকাশের মুখ দিয়ে কথা বলতে পেরেছে। এমনকি এটা বলেছিল। তারা এটা করতে ইচ্ছুক অথবা তাদের স্বপ্ন অপহরণ করতে ইচ্ছুক।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَالْخَفَّافُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَالُ أَقْوَامٍ يَرْفَعُونَ أَبْصَارَهُمْ إِلَى السَّمَاءِ فِي صَلَاتِهِمْ وَاشْتَدَّ قَوْلُهُ فِي ذَلِكَ حَتَّى قَالَ لَيَنْتَهُنَّ عَنْ ذَلِكَ أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ ‏","","",""],[11623,11623,"","আমরা বাবার ছেলেকে আমার মনের ভেতর থেকে কথা বলেছি এবং তার ভালবাসার জন্য লুকিয়ে থাকতে গেলাম। আর সিঁড়ি দিয়ে বলা হতো তারা মসজিদে থাকত আর তোমাকে যেতে দেবে না।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏وَعَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏قَالَ ‏ ‏اعْتَدِلُوا فِي السُّجُودِ وَلَا ‏ ‏يَفْتَرِشْ ‏ ‏أَحَدُكُمْ ذِرَاعَيْهِ كَالْكَلْبِ ‏","","",""],[11624,11624,"","আমরা বাবার ছেলের সাথে কথা বলেছি, আবেগ নিয়ে তার ছেলের সাথে কথা বলেছি এবং এক সুখী ঘন্টার জন্য ভীত হয়ে গেলাম। ঈশ্বরের কাছে প্রার্থনা আছে এবং সালাম বলল, আমি যেতে চাই এবং আমি তাকে সেখান থেকে বের করে দিতে চাই। মায়ের কান্নার তীব্রতার কারণে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏وَعَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَدْخُلُ الصَّلَاةَ وَأَنَا أُرِيدُ أَنْ أُطِيلَهَا فَأَسْمَعُ بُكَاءَ الصَّبِيِّ فَأَتَجَاوَزُ فِي صَلَاتِي مِمَّا أَعْلَمُ مِنْ شِدَّةِ ‏ ‏وَجْدِ ‏ ‏أُمِّهِ مِنْ بُكَائِهِ ‏","","",""],[11625,11625,"","আমি আমার মেধার সবচেয়ে ভালো দিক নিয়ে কথা বলেছি, যারা তাকে সাহায্য করতে চেয়েছিল তাদের জন্য টাকা নিয়ে আমরা কথা বলতাম । হিরো, আল্লাহ তাকে মেরে ফেলবে, আর সে ভালো কাজ করেছে আর আমি তার অর্থ পড়েছি যে ঈশ্বর তাকে জানেন আর সে একটা যুদ্ধলক আর ঈশ্বর জানেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ يَوْمَ الْفَتْحِ ‏ ‏مَكَّةَ ‏ ‏وَعَلَيْهِ ‏ ‏الْمِغْفَرُ ‏ ‏فَقِيلَ لَهُ إِنَّ ‏ ‏ابْنَ خَطَلٍ ‏ ‏مُتَعَلِّقٌ بِأَسْتَارِ ‏ ‏الْكَعْبَةِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَفِيمَا ‏ ‏قَرَأْتُ عَلَيْهِ ‏ ‏يَعْنِي ‏ ‏مَالِكٍ ‏ ‏قَالَ ‏ ‏وَلَمْ يَكُنْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ مُحْرِمًا وَاللَّهُ أَعْلَمُ ‏","","",""],[11626,11626,"","আমরা আমাদের ভাগ্যের কথা বলছি বাবা কি বলতে চাচ্ছেন আমি ভুলে গিয়েছিলাম আমি কি করতে হবে তা ভুলে গিয়েছিলাম। আমি বলতে চাচ্ছি, এই দিনটি আমরা কি করে ঈশ্বরের সাথে ছিলাম। তার জন্য প্রার্থনা করুন এবং তিনি তার শান্তির জন্য প্রার্থনা করেন এবং আমাদের মধ্যে আরো বড় অনেকে তা অস্বীকার করে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي بَكْرٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏كَيْفَ كُنْتُمْ تَصْنَعُونَ فِي هَذَا الْيَوْمِ ‏ ‏يَعْنِي يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهِلُّ ‏ ‏الْمُهِلُّ ‏ ‏مِنَّا فَلَا يُنْكِرُ عَلَيْهِ وَيُكَبِّرُ الْمُكَبِّرُ مِنَّا فَلَا يُنْكِرُ عَلَيْهِ ‏","","",""],[11627,11627,"","আমরা তার জন্য প্রার্থনা করা সম্পর্কে কথা বলেছি। তিনি বলেছেন, তিনি শহর থেকে একটি গাছ হস্তান্তর করা হয়েছে যে একটি গাছের ছায়াতে যাত্রীরা তার ছায়াতে চড়ে যাবে না। ওর সাথে কথা বল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ لَا يَقْطَعُهَا ‏ ‏قَالَ ‏ ‏فَحَدَّثْتُ بِهِ ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ بِهِ ‏","","",""],[11628,11628,"","আমরা দুই মাস ধরে সেই সব মানুষের জন্য ফুল নিয়ে কথা বলেছি, যারা ভাববাদীর জন্য নিজের ইচ্ছা আর ভুলের জন্য...","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَأَنْ ‏ ‏يُنْبَذَ ‏ ‏فِيهِ ‏","","",""],[11629,11629,"","আমরা ২ মাস ধরে ফুলের কথা বলেছি শেষ মানুষ তার কাছে যেন এটা জানতে পারে, ঐ দুইজন রহস্য আর ঐ দুইজন লোক, যারা আমার বাবাকে দেখে ফেলেছিল একটা আলো হিসেবে মুখ রাখবেন, তাদেরকে প্রমাণ করতে হবে যে, সেই দিনের শেষে কাপড় পড়ে থাকবে ।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏آخِرُ نَظْرَةٍ نَظَرْتُهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الِاثْنَيْنِ كَشَفَ السِّتَارَةَ وَالنَّاسُ خَلْفَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَنَظَرْتُ إِلَى وَجْهِهِ كَأَنَّهُ وَرَقَةُ مُصْحَفٍ فَأَرَادَ النَّاسُ أَنْ يَتَحَرَّكُوا فَأَشَارَ إِلَيْهِمْ أَنْ اثْبُتُوا وَيَلْقَى ‏ ‏السَّجْفَ ‏ ‏وَتُوُفِّيَ فِي آخِرِ ذَلِكَ الْيَوْمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11630,11630,"","আমরা দুজন ছেলে তার সম্বন্ধে কথা বলেছি যারা তার জন্য প্রার্থনা করেছে এবং তার কাছে প্রার্থনা করেছে এবং তারা তা করতে পারছে না। এবং ঈশ্বরের প্রভু হতে চেষ্টা করবেন না এবং তাকে তার সাথে থাকতে দেবেন না। স্বপ্নে যাও।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقَاطَعُوا وَلَا تَبَاغَضُوا وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا ‏ ‏تَحَاسَدُوا ‏ ‏وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا وَلَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثٍ ‏","","",""],[11631,11631,"","আমরা দুজন ছেলে তার সম্বন্ধে কথা বলেছি যারা বলেছে ছেলেটি নাকি ঈশ্বরের দোহাই পড়ে গেছে আর তাকে সূর্য থেকে জিজ্ঞাসা করা হয়েছে। ফিরে এসে সে ফিরে আসবে, আর সে আবার ফিরে আসবে আর বলবে সে একবার এটা খুঁজে পাবে। তার গলা বলেছে আমরা সিংহাসন বড় করেছি এবং ফিরে এসেছি।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَقَطَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ فَرَسٍ ‏ ‏فَجُحِشَ ‏ ‏شِقُّهُ ‏ ‏الْأَيْمَنُ فَدَخَلْنَا عَلَيْهِ نَعُودُهُ فَحَضَرَتْ الصَّلَاةُ فَصَلَّى قَاعِدًا وَصَلَّيْنَا قُعُودًا فَلَمَّا قَضَى الصَّلَاةَ قَالَ ‏ ‏إِنَّمَا الْإِمَامُ ‏ ‏لِيُؤْتَمَّ ‏ ‏بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً فَإِذَا سَجَدَ فَاسْجُدُوا ‏ ‏وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا وَلَكَ الْحَمْدُ وَإِنْ صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا أَجْمَعُونَ ‏","","",""],[11632,11632,"","আমরা ২ মাস মরুভূমি সম্পর্কে কথা বলেছি যারা সন্ধ্যার জন্য ঈশ্বরের কাছে প্রার্থনা করতো। আমি প্রতিজ্ঞা করছি, আমি তাকে অনেক কথা দেব। তুমি আমার মত মানুষ। আমি কি মনে করি, তুমি আমাকে তোমার সাথে রাখবে? দুই বছর পর তোমার সাথে আমার যার মত আছি।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ السَّاعَةِ فَقَالَ مَا أَعْدَدْتَ لَهَا قَالَ مَا أَعْدَدْتُ لَهَا مِنْ شَيْءٍ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً مَا أَعْدَدْتُ لَهَا كَثِيرَ شَيْءٍ ‏ ‏وَلَكِنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً أُخْرَى أَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏","","",""],[11633,11633,"","আমরা দুই মাস ধরে মরুভূমি সম্পর্কে কথা বলেছি যারা ঘুমাতে হয়েছে তাদের জন্য। রাতের খাবার খেতে প্রার্থনা করা শুরু করেছে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏وُضِعَ ‏ ‏الْعَشَاءُ وَأُقِيمَتْ الصَّلَاةُ فَابْدَءُوا بِالْعَشَاءِ ‏","","",""],[11634,11634,"","আমরা দুই মাস ধরে তার সম্বন্ধে কথা বলেছি। তার কাছে লোক আছে, ভাববাদী বলছে যে, ভাববাদী ঈশ্বরের কাছে এসে এই বিষ সরবরাহ করেছে। ১০ বছর বয়সী আমি একজন ছেলে, কিন্তু আমার ছেলে। মা আমাকে তার পর্দার উপর জাদু করার চেষ্টা করছে। আমার সাথে লড়বো আর বলছি, আমি সত্যি কথা বলছি।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَأَنَا ابْنُ عَشْرٍ وَمَاتَ وَأَنَا ابْنُ عِشْرِينَ وَكُنَّ ‏ ‏أُمَّهَاتِي تَحُثُّنِي عَلَى خِدْمَتِهِ فَدَخَلَ عَلَيْنَا فَحَلَبْنَا لَهُ مِنْ شَاةٍ ‏ ‏دَاجِنٍ ‏ ‏وَشِيبَ ‏ ‏لَهُ مِنْ بِئْرٍ فِي الدَّارِ وَأَعْرَابِيٌّ عَنْ يَمِينِهِ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏عَنْ يَسَارِهِ ‏ ‏وَعُمَرُ ‏ ‏نَاحِيَةً فَشَرِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏أَعْطِ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَنَاوَلَ الْأَعْرَابِيَّ وَقَالَ الْأَيْمَنُ فَالْأَيْمَنُ ‏ ‏و قَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً ‏ ‏الزُّهْرِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏أَنَسٌ ‏","","",""],[11635,11635,"","আমরা দুইটা ছেলের সাথে কথা বলেছি ফুল নিয়ে, অথবা ছেলেটির স্বপ্ন আছে, সাঁতার কাটা।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْلَمَ ‏ ‏عَلَى ‏ ‏صَفِيَّةَ ‏ ‏بِتَمْرٍ وَسَوِيقٍ ‏","","",""],[11636,11636,"","আমরা এটা শুনতে পাচ্ছি এবং আমাদের সময় দেখে, আমাদের সময় অনুসারে, আমি ভাববাদীর কাছে প্রার্থনা করছি তার কাছে প্রার্থনা করি এবং আমি আমার অনুগ্রহের জন্য শহর ও আমার অনুগ্রহের মাধ্যমে তা উদ্ধার করবো।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ بْنَ مَيْسَرَةَ ‏ ‏وحَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏سَمِعْتُهُمَا يَقُولَانِ سَمِعْنَا ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏أَرْبَعًا ‏ ‏وَبِذِي الْحُلَيْفَةِ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[11637,11637,"","দুই বছর ধরে আমার সাথে কথা বলার জন্য আমরা দু বছর কাজ করেছি, ঈশ্বর হয়তো আমার বাবা হতে পারেন, যেহেতু ছেলেটির কথা শুনে ঈশ্বরের কাছে তা বলেছে। তিনি এই তিনজন ঘটনা অনুসরণ করেছেন এবং আমি যা করি, তা করি।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏سَمِعَ ‏ ‏أَنَسًا ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَتْبَعُ الْمَيِّتَ ثَلَاثٌ أَهْلُهُ وَمَالُهُ وَعَمَلُهُ فَيَرْجِعُ اثْنَانِ وَيَبْقَى وَاحِدٌ أَهْلُهُ وَمَالُهُ وَيَبْقَى عَمَلُهُ ‏","","",""],[11638,11638,"","আমরা দুজন শয়তান কথা বলেছি যারা আমার বাবার সাথে কথা বলেছে, কিন্তু আমি কখনোই বিশ্বাস করতে পারিনি যে তিনি একজন দেবতা। আমরা দুজন আগে আমাদের বাড়িতে ছিলাম এবং আমরা দুই বছর আগে আমাদের বাড়িতে ছিলাম। বাড়িতে, আমাদের ঈশ্বরের ইচ্ছা চুরি করতে হয়েছিল, আর সে তা করবে, ঈশ্বর তাকে তাদের বাড়িতে আত্মসমর্পণ করতে বলেছেন এবং আমাদের মায়ের কাছে পৌঁছাতে বলে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ أَنَا وَيَتِيمٌ كَانَ عِنْدَنَا فِي الْبَيْتِ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً فِي بَيْتِنَا ‏ ‏خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَتَاهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي دَارِهِمْ وَصَلَّتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏خَلْفَنَا ‏","","",""],[11639,11639,"","আমরা দুই বছর ধরে বলছি যে আমি ঈশ্বরের কাছে যা পেয়েছি তা পেয়ে আমি... ...সে বলে, আমি এর থেকে পালিয়ে যাচ্ছি অথবা পানি পানের জন্য।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ فَبَالَ فِي الْمَسْجِدِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْرِيقُوا ‏ ‏عَلَيْهِ ‏ ‏ذَنُوبًا ‏ ‏أَوْ ‏ ‏سَجْلًا ‏ ‏مِنْ ‏ ‏مَاءٍ ‏","","",""],[11640,11640,"","আমি আমার বাবাকে দু'জন মৃত্যুর কথা বলেছি যারা বলেছে আমি ঈশ্বরের অনুগ্রহের জন্য প্রার্থনা করছি, শহরের দৃষ্টি এখন বড় হয়ে গেছে এবং দুই হাঁটুর পাতলা হয়ে পড়ে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ ‏ ‏بِالْمَدِينَةِ ‏ ‏أَرْبَعًا وَالْعَصْرَ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[11641,11641,"","দুই বছর আগে আমি আমার বাবার উত্তর সম্পর্কে কথা বলেছি যারা আমার ঈশ্বরের জন্য প্রার্থনা করেছে এবং আমি নই। দারুণ এবং পাশ দিয়ে যাওয়ার সময় তারা 'the witing' [the wile]","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏فَكَانُوا يَفْتَتِحُونَ ‏ ‏بِ ‏ { ‏الْحَمْدُ ‏}","","",""],[11642,11642,"","দুই বছর ধরে আমরা বলেছি লর্ডকে তার কাছে প্রার্থনা করতে দাও, আমাদের বাধা না হওয়া পর্যন্ত এই বিজয়টা কেটে ফেলা উচিত। আমি মুগ্ধ। তারা আমাকে বলল, আমি এটা করেছি। আমি এটা করতে চাই। আমি জানি না, আমি যদি আমার কাজ করি, আমি যদি আমার উপর এমন কিছু করতে পারি, তাহলে আমি যদি ভুল করি, তাহলে আমি কি করবো? আমি জানি, আমি জানি, আমি যদি আমি এটা করতে চাই, আমি এটা একটা সহজ হবে। আমি যদি আমি এটা করতে চাই, আমি এটা করতে চাই, আমি চাই, আমি এটা আমার জন্য ছেড়ে দেব। আমি যদি আমি চাই, আমি এটা করতে চাই, আমি চাই যে আমি চাই, আমি এটা করতে চাই, আমি চাই, আমি চাই, আমি এটা আমার কাছে একটা সহজ। আমি চাই। আমি যদি আমি চাই, আমি চাই, আমি চাই যে আমি চাই, আমি এটা আমার কাছে এটা একটা কাজ করি, আমি যদি তুমি জানো, আমি তোমার জন্য না। আমি এটা একটা কাজ করতে হবে। আমি তোমার জন্য। আমি চাই, আমি এটা একটা কাজ করতে পারি। আমি যদি তুমি জানো যে তুমি জানো না। আমি তোমার কাছে এটা একটা কাজ করতে পার যে তুমি জানো না। আমি তোমার জন্য, আমি তোমার কাছে এটা একটা কাজ করতে হবে। আমি তোমার কাছে এটা একটা কাজ করতে হবে। আমি তোমার জন্য। আমি তোমার কাছে এটা একটা","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قِيلَ ‏ ‏لِسُفْيَانَ ‏ ‏يَعْنِي ‏ ‏سَمِعَ مِنْ ‏ ‏أَنَسٍ ‏ ‏يَقُولُ ‏ ‏دَعَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَنْصَارَ ‏ ‏لِيُقْطِعَ لَهُمْ ‏ ‏الْبَحْرَيْنِ ‏ ‏فَقَالُوا لَا حَتَّى تُقْطِعَ لِإِخْوَانِنَا مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏مِثْلَنَا فَقَالَ ‏ ‏إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏فَاصْبِرُوا حَتَّى تَلْقَوْنِي ‏","","",""],[11643,11643,"","আমরা দুই বছর ধরে ভুল করে এসেছি যারা আমাকে জিতেছে। তারা আমার ডাইনিদের সাথে বের হয়ে গেছে, আর তারা তাকে দেখছে এটা বধির আর অনুমান করা হয়েছে। আর ঈশ্বরের জয়ে যাবে নরকে, তারপর সে শেষ হয়ে যাবে, আমরা ওই দুটো নেকড়ের মর্গে যাওয়ার পথ নিয়ে গেলাম, আমরা বেটেনটনে গেলাম, শিবিরগুলো জীবন্ত বলে ।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَبَّحَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏ ‏بُكْرَةً ‏ ‏وَقَدْ خَرَجُوا ‏ ‏بِالْمَسَاحِي ‏ ‏فَلَمَّا نَظَرُوا إِلَيْهِ قَالُوا ‏ ‏مُحَمَّدٌ ‏ ‏وَالْخَمِيسُ ‏ ‏مُحَمَّدٌ ‏ ‏وَالْخَمِيسُ ‏ ‏ثُمَّ أَحَالُوا يَسْعَوْنَ إِلَى الْحِصْنِ وَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَيْهِ ثُمَّ كَبَّرَ ثَلَاثًا ثُمَّ قَالَ ‏ ‏خَرِبَتْ ‏ ‏خَيْبَرُ ‏ ‏إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ فَأَصَبْنَا حُمُرًا خَارِجَةً مِنْ الْقَرْيَةِ فَاطَّبَخْنَاهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ وَرَسُولَهُ يَنْهَيَانِكُمْ عَنْ الْحُمُرِ الْأَهْلِيَّةِ فَإِنَّهَا ‏ ‏رِجْسٌ ‏ ‏مِنْ عَمَلِ الشَّيْطَانِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏مُحَمَّدٌ ‏ ‏وَالْخَمِيسُ ‏ ‏يَقُولُ وَالْجَيْشُ ‏","","",""],[11644,11644,"","আমরা দুই বছর ধরে কথা বলেছি মানুষ বলছে আল্লাহ কি খুঁজে পেয়েছেন আর একটা গোপন কথা জিজ্ঞেস করেছেন। তারা পাঠকদের বলত যে দুই ছেলে তাদের মুখে পড়ে গেছে। তিনি খুব ভালোভাবে সাহায্য লাভ করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَا وَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏سَرِيَّةٍ ‏ ‏مَا وَجَدَ عَلَيْهِمْ كَانُوا يُسَمَّوْنَ الْقُرَّاءَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏نَزَلَ فِيهِمْ بَلِّغُوا قَوْمَنَا عَنَّا أَنَّا قَدْ رَضِينَا وَرَضِيَ عَنَّا قِيلَ ‏ ‏لِسُفْيَانَ ‏ ‏فِيمَنْ نَزَلَتْ قَالَ فِي أَهْلِ ‏ ‏بِئْرِ مَعُونَةَ ‏","","",""],[11645,11645,"","সে এক বছরে আমি শুনেছি যে সে বলেনি সে কি বলেছে তাকে বলবে. সাহায্য সহ।","‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏عَاصِمًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏مَا وَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ مَا وَجَدَ عَلَى السَّبْعِينَ الَّذِينَ أُصِيبُوا ‏ ‏بِبِئْرِ مَعُونَةَ ‏","","",""],[11646,11646,"","সে দুটো জাহাজে পড়ে ছিল। যারা বলেছে, আল্লাহকে এটা করতে বলেছেন এবং তা ছেড়ে দিতে বলেছেন। আমাদের বাড়ির দুইজন ভাঁড় এবং তার সমর্থকরা বলেছেন, তিনি যেন আমার কথা বলছেন। ভাই","‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏عَاصِمًا ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏حَالَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَالْأَنْصَارِ ‏ ‏فِي دَارِنَا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏كَأَنَّهُ يَقُولُ آخَى ‏","","",""],[11647,11647,"","আমরা দুই বছর ধরে ঐ যমজদের কথা বলেছি... ...যে নবীকে তার কাছে পৌঁছে দিয়েছে আর সে তার হাতে আছে। আমি কি বেঁচে আছি এবং তোমার মা তাদের সাথে আছে যারা তাদের সাথে \"হ্যা ইশ্বরকে\" বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي سَفَرٍ وَكَانَ لَهُ ‏ ‏حَادٍ ‏ ‏يُقَالُ لَهُ ‏ ‏أَنْجَشَةُ ‏ ‏وَكَانَتْ ‏ ‏أُمُّ أَنَسٍ ‏ ‏مَعَهُمْ فَقَالَ يَا ‏ ‏أَنْجَشَةُ ‏ ‏رُوَيْدَكَ ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[11648,11648,"","আমরা দুই বছরের ভালো কথা বলেছি যারা সংবাদ শুনেছিলো... ...আর একে অপরের সাথে তর্ক করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي ‏ ‏بِالْبَيْدَاءِ ‏ ‏لَبَّيْكَ بِعُمْرَةٍ وَحَجَّةٍ مَعًا ‏","","",""],[11649,11649,"","আমরা দুই তলোয়ার কথা বলেছি আমরা ছেলে সের্রানের থেকে ভালো মানুষের কথা বলেছি যখন লর্ড তাকে আদেশ করল। জেল আর বলে দুই জন জীবন। বাবাকে একটা গুলি দিয়েছি, আর তারপর তাকে সহজ করে দেয়া দরকার।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَابْنُ سِيرِينَ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏رَمَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏وَنَحَرَ هَدْيَهُ ‏ ‏حَجَمَ ‏ ‏وَأَعْطَى ‏ ‏الْحَجَّامَ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً وَأَعْطَى الْحَالِقَ ‏ ‏شِقَّهُ ‏ ‏الْأَيْمَنَ فَحَلَقَهُ فَأَعْطَاهُ ‏ ‏أَبَا طَلْحَةَ ‏ ‏ثُمَّ حَلَقَ الْأَيْسَرَ فَأَعْطَاهُ النَّاسَ ‏","","",""],[11650,11650,"","আমরা দুজন ছেলে কথা বলেছি যাদের যৌন সম্পর্ক আর স্বপ্ন দেখা হচ্ছে, সবাই তাকে ভালোবাসে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَهْدَى ‏ ‏أُكَيْدِرُ ‏ ‏دُومَةَ ‏ ‏لِلنَّبِيِّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏يَعْنِي حُلَّةً ‏ ‏فَأَعْجَبَ النَّاسَ حُسْنُهَا فَقَالَ ‏ ‏لَمَنَادِيلُ ‏ ‏سَعْدٍ ‏ ‏فِي الْجَنَّةِ خَيْرٌ ‏ ‏أَوْ أَحْسَنُ ‏ ‏مِنْهَا ‏","","",""],[11651,11651,"","আমরা দুজন ছেলের কথা বলেছি, যাকে বলা হয়েছিল যে সবসময় তার হাত স্পর্শ করা মানুষ নয়। তোমার হাত আমাদের বলল, আমরা তাকে চুমু দিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ جُدْعَانَ ‏ ‏قَالَ قَالَ ‏ ‏ثَابِتٌ ‏ ‏لِأَنَسٍ ‏ ‏يَا ‏ ‏أَنَسُ ‏ ‏مَسِسْتَ يَدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِكَ قَالَ نَعَمْ قَالَ أَرِنِي أُقَبِّلُهَا ‏","","",""],[11652,11652,"","আমার বাবা একজন যিহোবার সাক্ষি ছিলেন আর আমি তাকে বাইবেল অধ্যয়ন করানোর জন্য আমন্ত্রণ জানাই । ক্লাস থেকে.","‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ مِنِ ‏ ‏ابْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَصَوْتُ ‏ ‏أَبِي طَلْحَةَ ‏ ‏فِي الْجَيْشِ خَيْرٌ مِنْ فِئَةٍ ‏","","",""],[11653,11653,"","আমরা দুই বছর আগে, ট্রাভেলারের শপথ শুনেছি... ...সে তার প্রার্থনা-নিচুরী আর লর্ডের গডফাদারের কাছে আছে. চেষ্টা করিনি, কবর থেকে যা শুনলাম তা করতে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعَ ‏ ‏قَاسِمٌ الرَّحَّالُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏خَرِبًا ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏وَكَانَ يَقْضِي فِيهَا حَاجَةً فَخَرَجَ إِلَيْنَا مَذْعُورًا ‏ ‏أَوْ فَزِعًا ‏ ‏وَقَالَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَسَأَلْتُ اللَّهَ تَبَارَكَ وَتَعَالَى أَنْ يُسْمِعَكُمْ مِنْ عَذَابِ أَهْلِ الْقُبُورِ مَا أَسْمَعَنِي ‏","","",""],[11654,11654,"","দুই বছর আগে আমরা কথা বলেছি যারা ঈশ্বরকে দেখে এবং ইচ্ছা করে ভেসেছে, তার মেয়ে এক রাতের জন্য গোসল করছে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُطِيفُ ‏ ‏بِنِسَائِهِ فِي لَيْلَةٍ يَغْتَسِلُ غُسْلًا وَاحِدًا ‏","","",""],[11655,11655,"","দুই বছর আগে আমরা শুনেছি, আমি তাদের বলতে শুনেছি যে, তাদের মন খারাপ হয়ে যাবে। লর্ড তার কাছে প্রার্থনা করল এবং আমি হয়ত তোমার সামনে নত হয়ে যাবো।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ بْنَ مَيْسَرَةَ ‏ ‏وَمُحَمَّدَ بْنَ الْمُنْكَدِرِ ‏ ‏يَقُولَانِ سَمِعْنَا ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏أَرْبَعًا ‏ ‏وَبِذِي الْحُلَيْفَةِ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[11656,11656,"","আমরা তো আগেই বলেছি, আমি একটা কলমের সিদ্ধান্তের কথা শুনেছি। সে তার প্রার্থনা শেষ করে দিয়েছে। সে বলেছে প্রত্যেক মাতাল বলেছে, গরীবের কাছে বলেছে, আমি যা বলেছি তা না বললেই গরু আর গরুও আমি বলি না। যদি তুমি জানতে চাও যে মাতালরা মাতাল আর মাতাল। পাপ আর শোকের জন্য।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُخْتَارَ بْنَ فُلْفُلٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏عَنْ الشُّرْبِ فِي الْأَوْعِيَةِ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُزَفَّتَةِ ‏ ‏وَقَالَ كُلُّ مُسْكِرٍ حَرَامٌ ‏ ‏قَالَ ‏ ‏قُلْتُ وَمَا ‏ ‏الْمُزَفَّتَةُ ‏ ‏قَالَ ‏ ‏الْمُقَيَّرَةُ ‏ ‏قَالَ قُلْتُ فَالرَّصَاصُ وَالْقَارُورَةُ قَالَ مَا ‏ ‏بَأْسٌ ‏ ‏بِهِمَا قَالَ قُلْتُ فَإِنَّ نَاسًا يَكْرَهُونَهُمَا قَالَ دَعْ مَا ‏ ‏يَرِيبُكَ ‏ ‏إِلَى مَا لَا ‏ ‏يَرِيبُكَ ‏ ‏فَإِنَّ كُلَّ مُسْكِرٍ حَرَامٌ قَالَ قُلْتُ لَهُ صَدَقْتَ السُّكْرُ حَرَامٌ فَالشَّرْبَةُ وَالشَّرْبَتَانِ عَلَى طَعَامِنَا قَالَ مَا أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ وَقَالَ الْخَمْرُ مِنْ الْعِنَبِ وَالتَّمْرِ وَالْعَسَلِ ‏ ‏وَالْحِنْطَةِ ‏ ‏وَالشَّعِيرِ وَالذُّرَةِ فَمَا خَمَّرْتَ مِنْ ذَلِكَ فَهِيَ الْخَمْرُ ‏","","",""],[11657,11657,"","আমরা আমার বাবার সাথে ঘুমের সময় কথা বলেছি, ঈশ্বরের কাছে প্রার্থনা করবে, যদি তার পানি প্রয়োজন হয়।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَبَرَّزَ لِحَاجَتِهِ أَتَيْتُهُ بِمَاءٍ فَيَغْسِلُ بِهِ ‏","","",""],[11658,11658,"","তিনি আমার জন্য ঈশ্বরের কাছে প্রার্থনা করেছেন এবং আমার ক্ষমতা রক্ষা করার জন্য আমার এক পুত্রকে শুনতেন ।","‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ جُدْعَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَصَوْتُ ‏ ‏أَبِي طَلْحَةَ ‏ ‏فِي الْجَيْشِ خَيْرٌ مِنْ فِئَةٍ ‏","","",""],[11659,11659,"","আমি বলেছিলাম, আমি যা করেছি তা ভুলে গিয়ে আমরা কতটা খুশি হয়েছি। ঈশ্বরের প্রার্থনাটা আমাকে স্বস্তি দিয়েছিল। তাকে বাড়ি গিয়ে ধোঁয়ায় আক্রান্ত হতে হবে। সে এটা নিয়ে চিন্তা করছে। তুমি তাকে বলতে চাচ্ছ, ঈশ্বরকে তার ছেলের দেখাশোনা করতে হবে। সে দ্বিতীয় দিনে মারা যাচ্ছে। এটা তার কাছে একটা ব্যাপার। এটা একটা ছোট ছোট বাচ্চা। এটা একটা ছোট বাচ্চা। এটা একটা ছোট বাচ্চা। তাকে অপরাধী বানিয়ে দাও.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ أَحَدًا كَانَ أَرْحَمَ بِالْعِيَالِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِبْرَاهِيمُ ‏ ‏مُسْتَرْضَعًا فِي ‏ ‏عَوَالِي ‏ ‏الْمَدِينَةِ ‏ ‏وَكَانَ يَنْطَلِقُ وَنَحْنُ مَعَهُ فَيَدْخُلُ الْبَيْتَ وَإِنَّهُ لَيُدَّخَنُ وَكَانَ ‏ ‏ظِئْرُهُ ‏ ‏قَيْنًا فَيَأْخُذُهُ فَيُقَبِّلُهُ ثُمَّ يَرْجِعُ قَالَ ‏ ‏عَمْرٌو ‏ ‏فَلَمَّا تُوُفِّيَ ‏ ‏إِبْرَاهِيمُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏ابْنِي وَإِنَّهُ مَاتَ فِي الثَّدْيِ فَإِنَّ لَهُ ‏ ‏ظِئْرَيْنِ ‏ ‏يُكْمِلَانِ رَضَاعَهُ فِي الْجَنَّةِ ‏","","",""],[11660,11660,"","আমরা কথা বলেছি, আমরা আমাদের প্রভু সম্পর্কে ভুলে যেতে বলেছিলাম। আপনার টাকা ভুলে যাওয়ার জন্য আপনার কাজ আমার কিছু টাকা আমার জন্য এবং একটি ভাল উপহার দিতে। স্বপ্ন, গ্রেস, তুমি আমার বাড়িতে খেয়ে তাকে \"বাবা\" বলে ডাক, যারা একজন লোক খুন করেছে... যে লোক মারা গেছে সে একজন পুরুষ খুন করেছে , সে একজন পুরুষই ছিল তার সমানে মানুষ । যে ব্যক্তি পুরুষ ও নারী আছে, সে এমন একজন মানুষ যে তার সঙ্গে একজন পুরুষ ও তার ছেলে আছে ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ الْمُنْذِرِ بْنِ الْجَارُودِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَنَعَ بَعْضُ عُمُومَتِي لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامًا فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أُحِبُّ أَنْ تَأْكُلَ فِي بَيْتِي وَتُصَلِّيَ فِيهِ قَالَ فَأَتَاهُ وَفِي الْبَيْتِ ‏ ‏فَحْلٌ ‏ ‏مِنْ تِلْكَ الْفُحُولِ ‏ ‏فَأَمَرَ بِجَانِبٍ مِنْهُ فَكُنِسَ وَرُشَّ فَصَلَّى وَصَلَّيْنَا مَعَهُ ‏","","",""],[11661,11661,"","আমরা সেই নিয়ম নিয়ে খুশি যে মানুষ তাদের সাথে কথা বলেছে যে আমার ভালোবাসা তার ভালবাসার জন্য প্রার্থনা করেছে, আমি কখনই তোমার মুখে এটা বলিনি আমি ভেবেছিলাম এটা হবে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَنَسًا ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَالُ أَقْوَامٍ يَرْفَعُونَ أَبْصَارَهُمْ فِي صَلَاتِهِمْ فَاشْتَدَّ قَوْلُهُ فِي ذَلِكَ حَتَّى قَالَ لَيَنْتَهُنَّ عَنْ ذَلِكَ أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ ‏","","",""],[11662,11662,"","আমরা ঈশ্বর খুঁজে পেতে সাহায্য করার চেষ্টা করে আমাদের সাহায্য করার চেষ্টা করেছি। আপনার টাকা আমি ভুলে গিয়েছিলাম তার জন্য ভালো ছিল এবং তার নিজের মহিলাদের জন্য আলো নিয়ে এসেছিল। চোয়াল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمَرْأَةُ مِنْ نِسَائِهِ يَغْتَسِلَانِ مِنْ إِنَاءٍ وَاحِدٍ وَكَانَ يَغْتَسِلُ بِخَمْسِ ‏ ‏مَكَاكِيَّ ‏ ‏وَيَتَوَضَّأُ ‏ ‏بِمَكُّوكٍ ‏","","",""],[11663,11663,"","আমরা আমাদের যা করতে বলা হয়েছে, সেই সম্বন্ধে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَعِدَ ‏ ‏أُحُدًا ‏ ‏فَتَبِعَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏فَرَجَفَ بِهِمْ الْجَبَلُ فَقَالَ ‏ ‏اسْكُنْ عَلَيْكَ نَبِيٌّ وَصِدِّيقٌ وَشَهِيدَانِ ‏","","",""],[11664,11664,"","আমি বলছি যে আমার বাবা কিছু করতে না চান। আমি বলছি, আপনি আমাকে বলেছেন যে ঈশ্বর আপনাকে রক্ষা করেছেন এবং হয়ত বলেছেন যে আমরা হয়ত বলতে পারি আমার বাবার সম্পর্কে ঈশ্বরকে শোক করা এবং পাথর মারার জন্য হৃদয়ের অবস্থা জানা যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَقُولَ ‏ ‏يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ قَالَ فَقُلْنَا يَا رَسُولَ اللَّهِ آمَنَّا بِكَ وَبِمَا جِئْتَ بِهِ فَهَلْ تَخَافُ عَلَيْنَا قَالَ فَقَالَ نَعَمْ إِنَّ الْقُلُوبَ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللَّهِ عَزَّ وَجَلَّ يُقَلِّبُهَا ‏","","",""],[11665,11665,"","ঈশ্বর তার মায়ের জন্য প্রার্থনা করেছেন এবং ঈশ্বর ঈশ্বরকে বলেন, ঈশ্বর তাঁর স্বপ্নগুলো দিয়েছেন, আর তিনি তাঁর জন্য যা তৈরি করেছেন, তা তিনি দিয়েছেন, মা সালিম।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏يُضْحِكُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَلَمْ تَرَ إِلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏مَعَهَا خِنْجَرٌ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَصْنَعِينَ بِهِ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏قَالَتْ أَرَدْتُ إِنْ ‏ ‏دَنَا ‏ ‏مِنِّي أَحَدٌ مِنْهُمْ طَعَنْتُهُ بِهِ ‏","","",""],[11666,11666,"","আমরা কয়েক বার কথা বলেছি একটা ছেলেকে শাস্তি দিতে যে ছিল না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏قُلْنَا ‏ ‏لِأَنَسِ بْنِ مَالِكٍ ‏ ‏مَا ‏ ‏أَنْكَرْتَ ‏ ‏مِنْ حَالِنَا فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَنْكَرْتُ أَنَّكُمْ لَا تُقِيمُونَ الصُّفُوفَ ‏","","",""],[11667,11667,"","আমি তার পেট থেকে ইচ্ছে করে আমার পেট ভরতি করতে লিখেছি","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[11668,11668,"","আমরা আপনার টাকা নিয়ে কথা বলেছি, অফিসারদের ব্যবহার করার জন্য তার প্রার্থনা এবং সেলম আছে, আমরা বলেছিলাম আমরা এখনও স্পর্শ করেছি বা ওসিদের কাছে যাই নি, তারপর সে চলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏مِسْحَاجٌ الضَّبِّيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏قَالَ كُنَّا إِذَا كُنَّا مَعَ النَّبِيِّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏فِي سَفَرٍ فَقُلْنَا ‏ ‏زَالَتْ الشَّمْسُ أَوْ لَمْ تَزُلْ صَلَّى الظُّهْرَ ثُمَّ ارْتَحَلَ ‏","","",""],[11669,11669,"","আমরা বাবার সাথে কথা বলেছি, বাবা সন্তানের জন্য আপনার টাকা নিয়ে এসেছিলেন, ঈশ্বর তার জীবন সমর্পণ করেছেন আর তিনি একজন দু:খজনক মেয়ে যে হয়ত তার শিকার হয়েছে। তিনি বলেছিলেন যে, তিনি আমাকে দেখেছেন । তিনি বলেছিলেন, ঈশ্বর তার কাছে প্রার্থনা করেন এবং তিনি আমার ভালবাসা দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏جِبْرِيلُ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ وَهُوَ جَالِسٌ ‏ ‏حَزِينٌ ‏ ‏قَدْ ‏ ‏خُضِبَ ‏ ‏بِالدِّمَاءِ ضَرَبَهُ بَعْضُ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏قَالَ فَقَالَ لَهُ وَمَا لَكَ قَالَ فَقَالَ لَهُ فَعَلَ بِي هَؤُلَاءِ وَفَعَلُوا قَالَ فَقَالَ لَهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتُحِبُّ أَنْ أُرِيَكَ ‏ ‏آيَةً ‏ ‏قَالَ نَعَمْ قَالَ فَنَظَرَ إِلَى شَجَرَةٍ مِنْ وَرَاءِ ‏ ‏الْوَادِي ‏ ‏فَقَالَ ادْعُ بِتِلْكَ الشَّجَرَةِ فَدَعَاهَا فَجَاءَتْ تَمْشِي حَتَّى قَامَتْ بَيْنَ يَدَيْهِ فَقَالَ مُرْهَا فَلْتَرْجِعْ فَأَمَرَهَا فَرَجَعَتْ إِلَى مَكَانِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَسْبِي ‏","","",""],[11670,11670,"","বেনের সঙ্গে আমরা কথা বলেছিলাম, আমরা প্রভুর সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ ‏ ‏وَالْهَرَمِ ‏ ‏وَالْبُخْلِ وَعَذَابِ الْقَبْرِ وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ ‏","","",""],[11671,11671,"","আমরা তোমাকে বলেছিলাম যে সে ওটা বানাতে প্ল্যান করেছে, সে পতাকা মেরে ফেলবে, ঘোড়াটা নিয়ে নিবে, নিয়ে যাও, নিয়ে যাও, যাও, যাও, যাও, তারপর আমি তাকে পরবর্তী সময়ের থেকে নিয়ে যাচ্ছি। ওর জন্য দরজা খুলে দাও, আমি দুঃখিত, তারা আমাদের পেয়ে খুশি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَخَذَ ‏ ‏الرَّايَةَ ‏ ‏زَيْدٌ ‏ ‏فَأُصِيبَ ثُمَّ أَخَذَهَا ‏ ‏جَعْفَرٌ ‏ ‏فَأُصِيبَ ثُمَّ أَخَذَهَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏فَأُصِيبَ وَإِنَّ عَيْنَيْهِ لَتَذْرِفَانِ ثُمَّ أَخَذَهَا ‏ ‏خَالِدٌ ‏ ‏مِنْ غَيْرِ ‏ ‏إِمْرَةٍ ‏ ‏فَفَتَحَ اللَّهُ عَلَيْهِ وَمَا يَسُرُّنِي أَنَّهُمْ عِنْدَنَا ‏ ‏أَوْ قَالَ مَا يَسُرُّهُمْ أَنَّهُمْ عِنْدَنَا ‏","","",""],[11672,11672,"","আমরা একটা ছেলের কথা বলেছিলাম যে তার মাস্টারের ব্যাপারে আমাদের কিছু বলেছে আমি তোমাকে বলেছিলাম আমরা তোমার পক্ষ থেকে লিখতে চাই না।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ابْنُ عُلَيَّةَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ زَاذَوَيْهِ ‏ ‏قَالَ قَالَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏نُهِينَا ‏ ‏أَوْ قَالَ أُمِرْنَا ‏ ‏أَنْ لَا نَزِيدَ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏عَلَى وَعَلَيْكُمْ ‏","","",""],[11673,11673,"","আমরা বিজ্ঞানের ছেলে সম্পর্কে কথা বলেছি মানুষ বলে এটা ঈশ্বরের প্রার্থনা ছিল. আমার বাবা এত প্রার্থনা করেছেন যে তিনি গাছের মাধ্যমে আছেন.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَقَارِبَةً وَصَلَاةُ ‏ ‏أَبِي بَكْرٍ ‏ ‏حَتَّى مَدَّ ‏ ‏عُمَرُ ‏ ‏فِي صَلَاةِ الْفَجْرِ ‏","","",""],[11674,11674,"","আমরা আমাদের কথা বলেছিলাম তুমি এটা করতে চাও কিনা, সে হার মানতে চায় কিনা, আমরা হাঁটু গেড়ে বসে তাকে জিজ্ঞেস করব, সকালে প্রার্থনা শেষে আমরা ঘুমাবো ড্রাইভ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏هَلْ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَعَمْ بَعْدَ الرُّكُوعِ ثُمَّ سُئِلَ بَعْدَ ذَلِكَ مَرَّةً أُخْرَى هَلْ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَلَاةِ الصُّبْحِ قَالَ نَعَمْ بَعْدَ الرُّكُوعِ يَسِيرًا ‏","","",""],[11675,11675,"","আমরা আমাদের কথা বলেছিলাম, কিভাবে এই ফোল্ডার রক্ষা করতে হয় যারা বলেছিল যে ভবিষ্যদ্বাণী তাকে দেয়া হয়েছে আর তাকে এটা করতে বলা হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ شَعْرُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى أَنْصَافِ أُذُنَيْهِ ‏","","",""],[11676,11676,"","আমরা ঈশ্বরকে কথা বলেছি তিনি তাঁর শান্তি এবং স্বপ্নের কথা বলেছেন। সকালে বললেন তিনি যেদিন বোমা হামলার সময় গিয়েছিলেন, তখন সূর্য থেকে তাকে মুক্তি দেয়া হয়। আগামীকালের প্রার্থনা দু'জন নয়, অথবা সে এই বার বলে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ وَقْتِ صَلَاةِ الصُّبْحِ قَالَ ‏ ‏فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏حِينَ طَلَعَ الْفَجْرُ فَأَقَامَ الصَّلَاةَ ثُمَّ أَسْفَرَ مِنْ الْغَدِ حَتَّى ‏ ‏أَسْفَرَ ‏ ‏ثُمَّ قَالَ أَيْنَ السَّائِلُ عَنْ وَقْتِ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏مَا بَيْنَ هَاتَيْنِ ‏ ‏أَوْ قَالَ هَذَيْنِ ‏ ‏وَقْتٌ ‏","","",""],[11677,11677,"","আমরা কথা বলেছি যে ঈশ্বর তাঁর শান্তির জন্য এসেছেন কিনা। সেই স্বাধীন মানুষ যিনি প্রার্থনা করার আগে চলে গেছেন। যে সে তার বন্ধুত্ব রক্ষা করতে পারে আর তার সবচেয়ে ভালো বন্ধুকে বলে যে আমার কাছে তার স্বাদ আছে, আমি জানি না সে তার বল কেটে ফেলেছে, নাকি সে তাকে বলে নি। ( গীতসংহিতা ১১৯: ১৬৬) ঈশ্বরের কাছে তার প্রার্থনা ও মুখ দিয়ে পাঠানো হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏النَّحْرِ ‏ ‏مَنْ كَانَ ذَبَحَ قَبْلَ الصَّلَاةِ فَلْيُعِدْ فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ هَذَا يَوْمٌ ‏ ‏يُشْتَهَى فِيهِ اللَّحْمُ وَذَكَرَ ‏ ‏هَنَةً ‏ ‏مِنْ جِيرَانِهِ فَكَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَّقَهُ قَالَ وَعِنْدِي ‏ ‏جَذَعَةٌ ‏ ‏هِيَ أَحَبُّ إِلَيَّ مِنْ شَاتَيْ لَحْمٍ قَالَ فَرَخَّصَ لَهُ فَلَا أَدْرِي بَلَغَتْ رُخْصَتُهُ مَنْ سِوَاهُ أَمْ لَا قَالَ ثُمَّ ‏ ‏انْكَفَأَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏إِلَى كَبْشَيْنِ فَذَبَحَهُمَا وَقَامَ النَّاسُ إِلَى ‏ ‏غُنَيْمَةٍ ‏ ‏فَتَوَزَّعُوهَا ‏ ‏أَوْ قَالَ فَتَجَزَّعُوهَا هَكَذَا قَالَ ‏ ‏أَيُّوبُ ‏","","",""],[11678,11678,"","আমরা আপনাদের টাকা ছেলেদের সাথে সেক্স করার ব্যাপারে কথা বলেছি, মদ খাও, আমি লড়াই করি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏شَرِبَ وَعَنْ يَمِينِهِ أَعْرَابِيٌّ وَعَنْ يَسَارِهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَنَاوَلَهُ وَقَالَ ‏ ‏الْأَيْمَنَ فَالْأَيْمَنَ ‏","","",""],[11679,11679,"","আমরা আমাদের কাছে ফিরে গিয়ে খুশি হয়েছি। আল্লাহ তার কাছে প্রার্থনা করেছেন এবং বললেন, আমি আল্লাহ্‌কে আদেশ দিয়েছি এবং তিনি যা বলেছেন, তা তিন বার বলে যাবেন। ( গীতসংহিতা ৩৭: ১১) আগুন ঈশ্বরের প্রতি বিশ্বাস এবং ঈশ্বরকে ভালোবাসে এবং আগুনে পুড়িয়ে ফেলা ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَوْفَلِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏فَقُلْنَا حَدِّثْنَا بِمَا سَمِعْتَ مِنْ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ثَلَاثٌ مَنْ كُنَّ فِيهِ حُرِّمَ عَلَى النَّارِ وَحُرِّمَتْ النَّارُ عَلَيْهِ ‏ ‏إِيمَانٌ بِاللَّهِ وَحُبُّ اللَّهِ وَأَنْ يُلْقَى فِي النَّارِ فَيُحْرَقَ أَحَبُّ إِلَيْهِ مِنْ أَنْ يَرْجِعَ فِي الْكُفْرِ ‏","","",""],[11680,11680,"","আমরা আনন্দের সাথে বলছি, আমরা শুধু তোমার টাকাই বললাম। আমার ছেলে এমন এক মৃত লোকের কাছ থেকে একটা আওয়াজ শুনতে পাবে যে মুখে মারা গেছে। আমি আল্লাহ্‌কে ফোন করেছি, তুমি যাও। কবর দিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحَائِطٍ ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏فَسَمِعَ صَوْتًا مِنْ قَبْرٍ فَقَالَ مَتَى مَاتَ صَاحِبُ هَذَا الْقَبْرِ قَالُوا مَاتَ فِي الْجَاهِلِيَّةِ فَقَالَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَدَعَوْتُ اللَّهَ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ ‏","","",""],[11681,11681,"","আমি আমার সবচেয়ে ভালো বন্ধুর সাথে একটা শাস্তির কথা বলেছি, কিন্তু আমি একটা ছেলে ঘুরে ঘুরে ঘুরে ঘুরে বেড়াই। আমি কখনোই তোমার কথা ভুলে যাইনি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عُبَيْدٍ الطَّائِيِّ ‏ ‏حَدَّثَنِي ‏ ‏بُشَيْرُ بْنُ يَسَارٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَنَسٌ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَقُلْنَا لَهُ مَا أَنْكَرْتَ مِنَّا مِنْ عَهْدِ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا أَنْكَرْتُ مِنْكُمْ شَيْئًا غَيْرَ أَنَّكُمْ لَا تُقِيمُونَ صُفُوفَكُمْ ‏","","",""],[11682,11682,"","ঈশ্বর আমার যোহানাতে আশীর্বাদ প্রদান করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَرَكَةُ فِي ‏ ‏نَوَاصِي ‏ ‏الْخَيْلِ ‏","","",""],[11683,11683,"","আমরা আনন্দের সাথে কথা বলেছি, সে শুনতে পাবে আর আমি সাহায্য করতে পারব না কিন্তু সে তার ইউনিফর্ম দেখে যেমন মনে হয়, তেমনই করতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْمَعُوا وَأَطِيعُوا وَإِنْ اسْتُعْمِلَ عَلَيْكُمْ حَبَشِيٌّ كَأَنَّ رَأْسَهُ زَبِيبَةٌ ‏","","",""],[11684,11684,"","আমরা নিশ্চিত ভাবে বলছি, যারা বলবে যে আল্লাহ এই কাজটি করেছেন তারা যেন এই ঘটনার কথা স্মরণ করে। তার ছেলে বলেছিল, আল্লাহ যেন তার আত্মার উপর অত্যাচার করেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِرَجُلٍ وَهُوَ ‏ ‏يُهَادَى ‏ ‏بَيْنَ ابْنَيْهِ قَالُوا نَذَرَ أَنْ يَمْشِيَ قَالَ ‏ ‏إِنَّ اللَّهَ لَغَنِيٌّ عَنْ تَعْذِيبِ هَذَا لِنَفْسِهِ فَأَمَرَهُ أَنْ يَرْكَبَ ‏","","",""],[11685,11685,"","আমরা এমন লোকেদের সঙ্গে মেলামেশা করতাম, যারা ঈশ্বরের জন্য প্রার্থনা করা হতো ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَجِيٌّ ‏ ‏لِرَجُلٍ حَتَّى نَعَسَ أَوْ كَادَ يَنْعَسُ بَعْضُ الْقَوْمِ ‏","","",""],[11686,11686,"","আমরা একটা হাত নিয়ে কথা বলেছি, সবাই আমার সব ক্ষতি করার জন্য প্রার্থনা করছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏عَنْ صَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ فَقَالَ ‏ ‏مَا كُنَّا نَشَاءُ أَنْ ‏ ‏نَرَاهُ مُصَلِّيًا إِلَّا رَأَيْنَاهُ وَلَا نَائِمًا إِلَّا رَأَيْنَاهُ ‏","","",""],[11687,11687,"","আমরা একজন মাস্টারের ব্যাপারে অনেক খুশি হয়েছি, যে কখনো ঈশ্বরের কাছে যায় নি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَنَادَى رَجُلٌ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَالْتَفَتَ إِلَيْهِ فَقَالَ لَمْ أَعْنِكَ قَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[11688,11688,"","আমরা একটা বাপ্তিস্মের বিষয়ে খুশি হয়েছি যার মানে হচ্ছে যে একটা ছেলে তার আত্মার জন্য চিকিৎসা গড়ে তুলেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি একটি ভাঁজের জন্য আত্মসমর্পণ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حَمَّادٍ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏مَنْ قَتَلَ كَافِرًا فَلَهُ ‏ ‏سَلَبُهُ ‏ ‏قَالَ ‏ ‏فَقَتَلَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏عِشْرِينَ ‏","","",""],[11689,11689,"","আমরা আমার ছেলেকে কিছু শুনতে সাহায্য করার কথা বলেছিলাম, আমি ঈশ্বরের অনুগ্রহের বিরুদ্ধে লড়াই করছি। পানি.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدِ بْنِ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ يَعْنِي الْأَنْصَارِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏دَخَلَ أَعْرَابِيٌّ الْمَسْجِدَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَالَ فَنَهَوْهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعُوهُ وَأَمَرَ أَنْ يُصَبَّ عَلَيْهِ ‏ ‏أَوْ ‏ ‏أُهَرِيقَ ‏ ‏عَلَيْهِ ‏ ‏الْمَاءُ ‏","","",""],[11690,11690,"","আমরা আনন্দের সাথে কথা বলেছি আমরা এক ছেলের জন্য কয়েক সেকেন্ড আগে এমন একটা ছেলের কথা বলেছি যে কিনা ঈশ্বরের দোহাইর কথা ভুলে গেছে। তাঁর তিন বছরের মেয়েকে শ্বাস নিতে গিয়ে তিনি তিন বছরের এক বৃদ্ধের মত শ্বাস নিতেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَزْرَةُ بْنُ ثَابِتٍ ‏ ‏عَنْ ‏ ‏ثُمَامَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَنَفَّسُ فِي إِنَائِهِ ثَلَاثًا ‏ ‏وَكَانَ ‏ ‏أَنَسٌ ‏ ‏يَتَنَفَّسُ ثَلَاثًا ‏","","",""],[11691,11691,"","আমরা একটি সুখী ছেলে কথা বলেছি যে আপনার ব্যাপারে জানতে চাইছে, যে কিনা আপনার ব্যাপারে প্রার্থনা করছে। ভাববাদীরা তার কাছে প্রার্থনা করেছে এবং তাকে উদ্ধার করবে। আপনি কিছু মজার বিষয় করেছেন এবং সেই অনুভূতি যা আপনি করেছেন। আপনি একটি দারুণ বিষয় নিয়ে কাজ করেছেন। আপনি যদি আপনার মনে হয়, আপনি একটি মহান শিক্ষক হতে পারেন, আপনি একটি মহান শিক্ষক, আপনি আপনার সাথে আছেন। আপনি যা আপনি আপনার আছে, আপনি কি মনে করেন, আপনি আপনার আছে? আপনি আপনার আছে, আপনি কি একটি মহান শিক্ষক? আপনার আছে? এবং আপনার আছে, আপনি আপনার আছে, আপনি কি মনে হয় আপনার সন্তান আপনার সন্তান আপনার কাছে এটা আপনার জন্য একটি ভাল কাজ করে দেবেন? এবং আপনার জন্য। আপনি যা আপনি একটি ভাল কাজ করে, এবং আপনি যা আপনি করতে পারেন, আপনি আপনার জন্য। আপনি আপনার জন্য একটি মহান সুযোগ আছে। আপনি যা আপনি করতে পারেন, আপনার জন্য। আপনি আপনার কাছে আপনার কাছে একটি বিষয় আপনার একটি বিষয় হবে। আপনার একটি বিশেষ উপায় আছে। আপনি আপনার জন্য একটি ধারণা আছে, আপনার কাছে যে আপনি যা আপনি আপনার কাছে আছে। আপনার কাছে আছে, আপনার একটি ধন্যবাদ। আপনি একটি ধন্যবাদ, আপনার কাছে আছে। আপনি একটি ধন্যবাদ। আপনি আপনার একটি ধন্যবাদ, আপনার একটি বিষয় আপনি আপনার কাছে আছে। আপনি একটি বিষয় আছে, এবং আপনার একটি ধন্যবাদ। আপনি একটি ধন্যবাদ। আপনি আপনার একটি ধন্যবাদ। আপনি ভালো খবর হল যে এটা কে উদ্ধার করতে হবে। যদি আমি একজনকে খুন করি তাহলে সে ভালো করবে। তুমি একটা তিন-টি ফাইল সমাধান করবে না... অথবা ফ্ল্যাটে ভরা গরু।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏الْأَخْضَرِ بْنِ عَجْلَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَكَا إِلَيْهِ الْحَاجَةَ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا عِنْدَكَ شَيْءٌ فَأَتَاهُ ‏ ‏بِحِلْسٍ ‏ ‏وَقَدَحٍ وَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَشْتَرِي هَذَا فَقَالَ رَجُلٌ أَنَا آخُذُهُمَا بِدِرْهَمٍ قَالَ مَنْ يَزِيدُ عَلَى دِرْهَمٍ فَسَكَتَ الْقَوْمُ فَقَالَ مَنْ يَزِيدُ عَلَى دِرْهَمٍ فَقَالَ رَجُلٌ أَنَا آخُذُهُمَا بِدِرْهَمَيْنِ قَالَ هُمَا لَكَ ثُمَّ قَالَ ‏ ‏إِنَّ الْمَسْأَلَةَ لَا تَحِلُّ إِلَّا لِأَحَدِ ثَلَاثٍ ذِي دَمٍ مُوجِعٍ أَوْ غُرْمٍ مُفْظِعٍ أَوْ فَقْرٍ مُدْقِعٍ ‏","","",""],[11692,11692,"","আমরা আপনাদের টাকার কথা বলেছিলাম, ঈশ্বরকে জিজ্ঞেস করার জন্য যে আপনার টাকা আমি তার কাছে এসেছি আর আমি তা করব না । প্রভু.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَانُوا يَفْتَتِحُونَ الْقِرَاءَةَ ‏ ‏بِ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏}","","",""],[11693,11693,"","আমরা একটা মানুষের সাথে কথা বলেছি যারা বলেছিল আমরা প্রভুর বার্তাবাহকের কাছে প্রার্থনা করছি। আমার মনে হয় আমরা একটা মই তৈরি করেছি আর সে কি আশা করছে তা দেখে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَغْرِبَ ثُمَّ يَجِيءُ أَحَدُنَا إِلَى ‏ ‏بَنِي سَلِمَةَ ‏ ‏وَهُوَ يَرَى مَوَاقِعَ نَبْلِهِ ‏","","",""],[11694,11694,"","আমরা একজন নিশ্চিত রক্ষকের ব্যাপারে কথা বলেছি, যে বাবাকে বলেছে তার বাবার জন্য পেইন্টকর আছে। সে বলবে, সে আমাদের ভালবাসার কারণে বেঁচে আছে, বাবা, বাবা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏لِأَبِي طَلْحَةَ ‏ ‏ابْنٌ يُقَالُ لَهُ ‏ ‏أَبُو عُمَيْرٍ ‏ ‏وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضَاحِكُهُ قَالَ فَرَآهُ حَزِينًا فَقَالَ يَا ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏","","",""],[11695,11695,"","আমরা একটা হাত নিয়ে কথা বলেছি যেটা বলে আমি মানুষকে বলছি যে তৃতীয় জনকে মারতে। তারপর, অনুপ্রবেশকারীকে বলা হচ্ছে এমন কেউ যে তোমার মজা করছে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏عَنْ بَيْعِ الثَّمَرِ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ثَمَرَةِ النَّخْلِ حَتَّى ‏ ‏تَزْهُوَ ‏ ‏قِيلَ ‏ ‏لِأَنَسٍ ‏ ‏مَا ‏ ‏تَزْهُو ‏ ‏قَالَ تَحْمَرُّ ‏","","",""],[11696,11696,"","আমরা যখন সেখানে পৌঁছাই, তখন বাবা এক বছর বয়স থেকেই তার কাছে প্রার্থনা করেছেন । রিফ আর বানরের লোকেরা এটা চেষ্টা করতে বলেছে, তারা এটা বলেনি.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏وَقَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَلَدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْخَمْرِ بِالْجَرِيدِ وَالنِّعَالِ وَجَلَدَ ‏ ‏أَبُو بَكْرٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فِي حَدِيثِهِ أَرْبَعِينَ ‏ ‏فَلَمَّا كَانَ ‏ ‏عُمَرُ ‏ ‏دَنَا النَّاسُ مِنْ الرِّيفِ وَالْقُرَى قَالَ لِأَصْحَابِهِ مَا تَرَوْنَ قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏اجْعَلْهَا كَأَخَفِّ الْحُدُودِ فَجَلَدَ ‏ ‏عُمَرُ ‏ ‏ثَمَانِينَ ‏","","",""],[11697,11697,"","আমরা এক ভালো শ্‌হামসনের কথা বলেছিলাম, যাকে ঈশ্বরের কাছে প্রার্থনা করতে হতো । হতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِخَيْبَرَ ‏ ‏فَقَالَ أَكَلْتُ الْحُمُرَ مَرَّتَيْنِ قَالَ ثُمَّ جَاءَ فَقَالَ أَفْنَيْتُ الْحُمُرَ قَالَ فَنَادَى إِنَّ اللَّهَ وَرَسُولَهُ ‏ ‏يَنْهَيَانِكُمْ عَنْ لَحْمِ الْحُمُرِ فَإِنَّهَا ‏ ‏رِجْسٌ ‏","","",""],[11698,11698,"","আমরা কিছু সময় কথা বলেছি, তিনি বলেছিলেন আমি ভাববাদীর কাছে প্রার্থনা করি আর ঈশ্বর তাকে হত্যা করার জন্য ঈশ্বর তাকে বলেন। তারা আমাদের সব বলে দেবে। তারা তর্ক করবে যেমন সে বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَأَلَ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا إِنَّ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏يُسَلِّمُونَ عَلَيْنَا فَكَيْفَ نَرُدُّ عَلَيْهِمْ قَالَ ‏ ‏فَقُولُوا وَعَلَيْكُمْ ‏ ‏وَحَجَّاجٌ ‏ ‏مِثْلَهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَمْ أَسْأَلْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ هَذَا الْحَدِيثِ هَلْ سَمِعْتَهُ مِنْ ‏ ‏أَنَسٍ ‏","","",""],[11699,11699,"","আমরা কথা বলেছি, আমরা কি করে তাদের শাসন করবো যাদের ছেলে ছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَهْرَمُ ‏ ‏ابْنُ ‏ ‏آدَمَ ‏ ‏وَتَبْقَى مِنْهُ اثْنَتَانِ الْحِرْصُ وَالْأَمَلُ ‏","","",""],[11700,11700,"","আমার বাবা কী করেছিলেন, তা দেখুন, কিন্তু তার একটা ছেলে এসে আমার ছেলেকে খুঁজে পান ও একটা রাজ্যে খুঁজে পান সে বলেছিল, তুমি একজন অজানা লোকের বাবা যে তাকে হত্যা করেছে বা তাকে হত্যা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏بَدْرٍ ‏ ‏مَنْ يَنْظُرُ مَا فَعَلَ ‏ ‏أَبُو جَهْلٍ ‏ ‏فَانْطَلَقَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏فَوَجَدَ ابْنَيْ ‏ ‏عَفْرَاءَ ‏ ‏قَدْ ضَرَبَاهُ حَتَّى ‏ ‏بَرَدَ ‏ ‏فَأَخَذَ بِلِحْيَتِهِ فَقَالَ أَنْتَ ‏ ‏أَبُو جَهْلٍ ‏ ‏فَقَالَ وَهَلْ فَوْقَ رَجُلٍ قَتَلْتُمُوهُ ‏ ‏أَوْ قَتَلَهُ قَوْمُهُ ‏","","",""],[11701,11701,"","আমি তাকে রাখতে চাইনি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏لَنْ تَنَالُوا ‏ ‏الْبِرَّ ‏ ‏حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ ‏} ‏وَ ‏ { ‏مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا ‏} ‏قَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَا رَسُولَ اللَّهِ وَحَائِطِي الَّذِي كَانَ بِمَكَانِ كَذَا وَكَذَا وَاللَّهِ لَوْ اسْتَطَعْتُ أَنْ أُسِرَّهَا لَمْ أُعْلِنْهَا قَالَ ‏ ‏اجْعَلْهُ فِي ‏ ‏فُقَرَاءِ أَهْلِكَ ‏","","",""],[11702,11702,"","আমরা এমন একদল ব্যক্তির সম্বন্ধে কথা বলেছিলাম, যারা সবচেয়ে শক্তিশালী ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الدَّجَّالَ ‏ ‏أَعْوَرُ الْعَيْنِ الشِّمَالِ عَلَيْهَا ‏ ‏ظَفَرَةٌ ‏ ‏غَلِيظَةٌ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ ‏ ‏قَالَ وَكُفْرٌ ‏","","",""],[11703,11703,"","আমরা একটি সুখী ছেলের কথা বলেছি, বাবার সাথে যুদ্ধ করার অভ্যাসের জন্য, যে একটি ছেলে তাদের সাথে কথা বলেছে, ঈশ্বর বলতে হবে আমি যা করছি তা তাদের প্রার্থনায় দেখতে। এটা তাদের স্বপ্নকে ধারণ করার পরিকল্পনা বা পরিকল্পনা না করা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَالُ أَقْوَامٍ يَرْفَعُونَ أَبْصَارَهُمْ إِلَى السَّمَاءِ فِي صَلَاتِهِمْ فَاشْتَدَّ قَوْلُهُ فِي ذَلِكَ حَتَّى قَالَ لَيَنْتَهُنَّ عَنْ ذَلِكَ أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ ‏","","",""],[11704,11704,"","আমরা কিভাবে তাদের উপর শাসন করব সে সম্পর্কে আমরা কথা বলেছি, আমি তার সাথে যেতে পারলে তার প্রশংসা করতাম।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحَّى بِكَبْشَيْنِ أَقْرَنَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏لَقَدْ رَأَيْتُهُ يَذْبَحُهُمَا بِيَدِهِ وَاضِعًا عَلَى ‏ ‏صِفَاحِهِمَا ‏ ‏قَدَمَهُ وَيُسَمِّي وَيُكَبِّرُ ‏","","",""],[11705,11705,"","ঈশ্বর এবং মসজিদ আমাকে আমার ধারণা এবং এই বিষয়টি দেখার জন্য আমাকে আপনার সাথে দেখা করতে হবে। হয়তো সে আমাকে বলেছে কে আমাকে দেখাতে যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتِمُّوا الرُّكُوعَ وَالسُّجُودَ فَوَاللَّهِ إِنِّي لَأَرَاكُمْ مِنْ بَعْدِي ‏ ‏وَرُبَّمَا قَالَ مِنْ وَرَاءِ ظَهْرِي ‏ ‏إِذَا رَكَعْتُمْ وَإِذَا سَجَدْتُمْ ‏","","",""],[11706,11706,"","আমরা কথা দিয়েছিলাম, আমরা কিভাবে তাদের খুঁজে বের করতে চেষ্টা করেছি যাদের এটা করতে হবে, কালোরা ভেঙ্গে যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اعْتَدِلُوا فِي السُّجُودِ وَلَا يَبْسُطْ أَحَدُكُمْ ذِرَاعَيْهِ انْبِسَاطَ الْكَلْبِ ‏","","",""],[11707,11707,"","ঈশ্বর প্রেমের এক এলাকাকে আহ্বান করেন এবং পরে এটাকে ছেড়ে দেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا بَعْدَ الرُّكُوعِ يَدْعُو عَلَى حَيٍّ مِنْ أَحْيَاءِ ‏ ‏الْعَرَبِ ‏ ‏ثُمَّ تَرَكَهُ ‏","","",""],[11708,11708,"","আমরা এমন একদল বন্ধুর কথা বলেছিলাম যারা আগে জেলে ছিল না। তোমার মুখে আমার হাত ঘষাছিল, তাই আমি তোমার ঈশ্বর তোমাকে দেব। ক্ষমা আর দয়া।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَإِذَا أَنَا بِنَهْرٍ حَافَتَاهُ خِيَامُ اللُّؤْلُؤِ فَضَرَبْتُ بِيَدِي فِي مَجْرَى الْمَاءِ فَإِذَا مِسْكٌ أَذْفَرُ قُلْتُ يَا ‏ ‏جِبْرِيلُ ‏ ‏مَا هَذَا قَالَ هَذَا الْكَوْثَرُ الَّذِي أَعْطَاكَ اللَّهُ ‏ ‏أَوْ أَعْطَاكَ رَبُّكَ عَزَّ وَجَلَّ ‏","","",""],[11709,11709,"","আমরা আনন্দের সঙ্গে আমার বাবার সঙ্গে কথা বলেছিলাম, তিনি বলেছিলেন যে তিনি আসলে কী বোঝাতে চেয়েছেন । ঈশ্বরের কাছে আটকে ছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا بَعْدَ الرُّكُوعِ يَدْعُو عَلَى ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَقَالَ ‏ ‏عُصَيَّةُ ‏ ‏عَصَتْ اللَّهَ وَرَسُولَهُ ‏","","",""],[11710,11710,"","আমরা বাবার বিয়ের ব্যাপারে অনেক কথা বলেছি, সে তোমাকে বলবে যদি সে কখনো জিততে চায়, যদি তুমি ঘুমাতে চাও, তুমি বলবে তুমি ড্রিংক করবে আমি তোমাকে যা বলতে পারি সব কিছু বলার শেখানো হয়েছে। আমার প্রভু আর যার জন্য প্রার্থনা করব, তার জন্য প্রার্থনা করবো, কিন্তু তিনি প্রথমে হবেন। তারা তাকে তার জীবনের অনুগ্রহ দিয়ে তার কাজ করার পরিকল্পনা করবে না। সে বলবে সে ওখানে নেই এবং তারা সেখানে নেই। ঈশ্বর ক্ষমা করে দিয়েছেন এবং তাঁর সমস্ত আনন্দ আছে বলে যে তারা সেখানে নেই। হতে পারে আল্লাহ আপনার পাপের জন্য যা করেছেন এবং আপনি যা করতে যাচ্ছেন তা নিয়ে অনেক দেরী করেছেন। বলতেই হচ্ছে ভাল. আমি জিতবো. সে আমাকে কিছু বলতে দেবে না সে আমাকে কিছু বলবে না তারপর সে আমাকে বলবে সে আমাকে একটা সীল তুলে দেবে, তারপর আমি তার কাছ থেকে শিখতে দেব, তারপর আমি সেটা খুঁজে বের করব. আমি আমার লর্ডকে একটা ভালো কাজ করতে দিতে দিতে পারি, আর তারপর বলে দিচ্ছি এটা একটা ভালো কাজ। তুমি আমার প্রেসিডেন্টকে টাকা দিতে যাচ্ছ, আমি তাকে কথা দিচ্ছি। তারপর আমি একা একজনকে খুঁজে বের করবো। আমি আমার লর্ডকে দেখতে পেয়েছি অথবা ঈশ্বরের সাথে যুদ্ধ করতে গিয়ে আল্লাহ আমাকে সাহায্য করুন। আর তারপর আমি মনে করি এটা আপনার জন্য একটা হাত এবং তারপর আমি আছি। এবং তারপর আমি এখন আমি এক হাত। এবং তারপর আমি একটি মাত্র জিনিস খুঁজে বের করব, আমি আপনাকে একটি হাত খুঁজে বের করব এবং তারপর আমি একটি হাত পাব। এবং তারপর আমি একটি হাত করব, অথবা আমি একটি জিনিস যে কি করতে পারি, অথবা আমি এর জন্য। এবং আমি আপনাকে সাহায্য করব, অথবা আপনি একটি জিনিস পাবেন। এবং তারপর আমি আপনার জন্য একটি সাহায্য করতে হবে, অথবা আপনি একটি হাত এবং তারপর আমি একটি হাত পাবেন। এবং তারপর আমি একটি হাত পাবেন এবং তারপর আমি একটি হাত পাবেন এবং তারপর আমি একটি হাত পাবেন এবং তারপর আমি আপনার জন্য একটি হাত আমি বলতে চাচ্ছি, ঈশ্বর, আমি সেই পবিত্র পিতা নই, যে আমাদের সাথে কথা বলেছে। সে আগুনের বাইরে, সে তার হৃদয় থেকে ঈশ্বরের কাছে নয়। ঈশ্বর তার ভালোর জন্য তার হৃদয়ের মধ্যে ছিলেন আর তারপর তিনি অগ্নি থেকে বেরিয়ে আসেন, যিনি তাকে বলেছিলেন যেন তিনি ঈশ্বরকে না বলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَرُوبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَجْتَمِعُ الْمُؤْمِنُونَ يَوْمَ الْقِيَامَةِ فَيُلْهَمُونَ ذَلِكَ فَيَقُولُونَ لَوْ اسْتَشْفَعْنَا عَلَى رَبِّنَا عَزَّ وَجَلَّ فَأَرَاحَنَا مِنْ مَكَانِنَا هَذَا فَيَأْتُونَ ‏ ‏آدَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَيَقُولُونَ يَا ‏ ‏آدَمُ ‏ ‏أَنْتَ أَبُو الْبَشَرِ خَلَقَكَ اللَّهُ عَزَّ وَجَلَّ بِيَدِهِ وَأَسْجَدَ لَكَ مَلَائِكَتَهُ وَعَلَّمَكَ أَسْمَاءَ كُلِّ شَيْءٍ فَاشْفَعْ لَنَا إِلَى رَبِّنَا عَزَّ وَجَلَّ يُرِيحُنَا مِنْ مَكَانِنَا هَذَا فَيَقُولُ لَهُمْ ‏ ‏آدَمُ ‏ ‏لَسْتُ هُنَاكُمْ وَيَذْكُرُ ذَنْبَهُ الَّذِي أَصَابَ ‏ ‏فَيَسْتَحْيِي رَبَّهُ عَزَّ وَجَلَّ وَيَقُولُ وَلَكِنْ ائْتُوا ‏ ‏نُوحًا ‏ ‏فَإِنَّهُ أَوَّلُ رَسُولٍ بَعَثَهُ اللَّهُ إِلَى الْأَرْضِ فَيَأْتُونَ ‏ ‏نُوحًا ‏ ‏فَيَقُولُ لَسْتُ هُنَاكُمْ وَيَذْكُرُ لَهُمْ خَطِيئَتَهُ وَسُؤَالَهُ رَبَّهُ عَزَّ وَجَلَّ مَا لَيْسَ لَهُ بِهِ عِلْمٌ ‏ ‏فَيَسْتَحْيِي رَبَّهُ بِذَلِكَ وَلَكِنْ ائْتُوا ‏ ‏إِبْرَاهِيمَ خَلِيلَ الرَّحْمَنِ ‏ ‏عَزَّ وَجَلَّ فَيَأْتُونَ فَيَقُولُ لَسْتُ هُنَاكُمْ وَلَكِنْ ائْتُوا ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏عَبْدًا كَلَّمَهُ اللَّهُ وَأَعْطَاهُ التَّوْرَاةَ فَيَأْتُونَ ‏ ‏مُوسَى ‏ ‏فَيَقُولُ لَسْتُ هُنَاكُمْ وَيَذْكُرُ لَهُمْ النَّفْسَ الَّتِي قَتَلَ بِغَيْرِ نَفْسٍ ‏ ‏فَيَسْتَحْيِي رَبَّهُ مِنْ ذَلِكَ وَلَكِنْ ائْتُوا ‏ ‏عِيسَى ‏ ‏عَبْدَ اللَّهِ وَرَسُولَهُ وَكَلِمَتَهُ وَرُوحَهُ فَيَأْتُونَ ‏ ‏عِيسَى ‏ ‏فَيَقُولُ لَسْتُ هُنَاكُمْ وَلَكِنْ ائْتُوا ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبْدًا غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ فَيَأْتُونِي ‏ ‏قَالَ ‏ ‏الْحَسَنُ ‏ ‏هَذَا الْحَرْفَ ‏ ‏فَأَقُومُ ‏ ‏فَأَمْشِي بَيْنَ ‏ ‏سِمَاطَيْنِ ‏ ‏مِنْ الْمُؤْمِنِينَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏حَتَّى أَسْتَأْذِنَ عَلَى رَبِّي عَزَّ وَجَلَّ فَيُؤْذَنَ لِي فَإِذَا رَأَيْتُ رَبِّي وَقَعْتُ ‏ ‏أَوْ خَرَرْتُ ‏ ‏سَاجِدًا إِلَى رَبِّي عَزَّ وَجَلَّ فَيَدَعُنِي مَا شَاءَ اللَّهُ أَنْ يَدَعَنِي قَالَ ثُمَّ يُقَالُ ‏ ‏ارْفَعْ ‏ ‏مُحَمَّدُ ‏ ‏قُلْ تُسْمَعْ وَسَلْ ‏ ‏تُعْطَهْ وَاشْفَعْ تُشَفَّعْ فَأَرْفَعُ رَأْسِي فَأَحْمَدُ بِتَحْمِيدٍ يُعَلِّمُنِيهِ ثُمَّ أَشْفَعُ فَيَحُدُّ لِي حَدًّا فَأُدْخِلُهُمْ الْجَنَّةَ ثُمَّ أَعُودُ إِلَيْهِ الثَّانِيَةَ فَإِذَا رَأَيْتُ رَبِّي عَزَّ وَجَلَّ وَقَعْتُ ‏ ‏أَوْ خَرَرْتُ ‏ ‏سَاجِدًا لِرَبِّي فَيَدَعُنِي مَا شَاءَ اللَّهُ أَنْ يَدَعَنِي ثُمَّ يُقَالُ ارْفَعْ ‏ ‏مُحَمَّدُ ‏ ‏قُلْ تُسْمَعْ وَسَلْ ‏ ‏تُعْطَهْ وَاشْفَعْ تُشَفَّعْ فَأَرْفَعُ رَأْسِي فَأَحْمَدُهُ بِتَحْمِيدٍ يُعَلِّمُنِيهِ ثُمَّ أَشْفَعُ فَيَحُدُّ لِي حَدًّا فَأُدْخِلُهُمْ الْجَنَّةَ ثُمَّ أَعُودُ إِلَيْهِ الثَّالِثَةَ فَإِذَا رَأَيْتُ رَبِّي وَقَعْتُ ‏ ‏أَوْ خَرَرْتُ ‏ ‏سَاجِدًا لِرَبِّي عَزَّ وَجَلَّ فَيَدَعُنِي مَا شَاءَ اللَّهُ أَنْ يَدَعَنِي ثُمَّ يُقَالُ ارْفَعْ ‏ ‏مُحَمَّدُ ‏ ‏وَقُلْ تُسْمَعْ وَسَلْ ‏ ‏تُعْطَهْ وَاشْفَعْ تُشَفَّعْ فَأَرْفَعُ رَأْسِي فَأَحْمَدُهُ بِتَحْمِيدٍ يُعَلِّمُنِيهِ ثُمَّ أَشْفَعُ فَيَحُدُّ لِي حَدًّا فَأُدْخِلُهُمْ الْجَنَّةَ ثُمَّ أَعُودُ الرَّابِعَةَ فَأَقُولُ يَا رَبِّ مَا بَقِيَ إِلَّا مَنْ حَبَسَهُ الْقُرْآنُ فَحَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَيَخْرُجُ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَكَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ شَعِيرَةً ثُمَّ يَخْرُجُ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَكَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ بُرَّةً ثُمَّ يَخْرُجُ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَكَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ ذَرَّةً ‏","","",""],[11711,11711,"","আমরা এতিমত্ব নিয়ে কথা বলেছি। আমি শুনেছি মানুষ বলছে আমি কে। আমি বলেছি ঈশ্বর আমাকে জিজ্ঞেস করেছেন আমি কে। আমি আগুন থেকে দূরে সরেছি। একবার আমাকে বলেছি যে আমাকে মিথ্যা বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ قَالَهُ مَرَّتَيْنِ ‏ ‏وَقَالَ مَرَّةً مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏","","",""],[11712,11712,"","আমরা একে অপরের সাথে কথা বলেছি, আমি এই নিয়ম নিয়ে খুশি যে ছেলেটি তার শান্তি ফিরিয়ে দিয়েছে। আমি তাদের প্রার্থনাতে তাদের লাথি মেরে বলবো এবং বলে দেব, যতক্ষণ না আমি বলবো আমি তোমাকে মেরে ফেলবো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَنَسًا ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَالُ أَقْوَامٍ يَرْفَعُونَ أَبْصَارَهُمْ فِي صَلَاتِهِمْ قَالَ فَاشْتَدَّ فِي ذَلِكَ حَتَّى قَالَ لَيَنْتَهُنَّ عَنْ ذَلِكَ أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ ‏","","",""],[11713,11713,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং সেই মহিলাকে তার লোকেদের কাছে সমর্পণ করেছেন, যারা হয়তো আমাকে ছেড়ে চলে যাবে । একটা পানি থেকে পানি থেকে তাড়িয়ে তার আত্মা থেকে গান শোনাও, আর তোমার মুড়ি সাদা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمَرْأَةُ مِنْ نِسَائِهِ ‏ ‏يَغْتَسِلَانِ مِنْ إِنَاءٍ وَاحِدٍ وَكَانَ يَغْتَسِلُ بِخَمْسِ ‏ ‏مَكَاكِيَّ ‏ ‏وَيَتَوَضَّأُ ‏ ‏بِمَكُّوكٍ ‏","","",""],[11714,11714,"","আমরা একটি সুখী ছেলে কথা বলেছি যে আমাদের সাথে ঈশ্বরের প্রেমের কথা বলেছে যখন আমার বাবা ঈশ্বরের প্রতি কথা বলেছে, ঈশ্বর ঈশ্বরের অনুগ্রহ লাভ করেছেন এবং রাজার সাথে খাওয়ালেন। \"আমি কি দয়া করে হতে পারি, তাহলে আল্লাহ তার কাপড় জিতেছেন, তিনি বললেন, \"ঈশ্বর, অথবা সুখী, অথবা তিনি যা বলেছিলেন, তা ভুলে গেছেন।\" তার মা ঈশ্বরের পাপের কথা বলেছে। যারা ঈশ্বরের কাছে প্রার্থনা করেছে, তাদের জন্য যারা তা করে চলেছে এবং তা প্রদান করবে ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏وَكَّلَ بِالرَّحِمِ مَلَكًا قَالَ أَيْ رَبِّ ‏ ‏نُطْفَةٌ ‏ ‏أَيْ رَبِّ ‏ ‏عَلَقَةٌ ‏ ‏أَيْ رَبِّ ‏ ‏مُضْغَةٌ ‏ ‏فَإِذَا قَضَى الرَّبُّ عَزَّ وَجَلَّ خَلْقَهَا قَالَ ‏ ‏أَيْ رَبِّ أَشَقِيٌّ أَوْ سَعِيدٌ ذَكَرًا أَوْ أُنْثَى فَمَا الرِّزْقُ وَمَا الْأَجَلُ قَالَ فَيَكْتُبُ كَذَلِكَ فِي بَطْنِ أُمِّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏بِمَكَّةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرِ بْنِ أَنَسٍ أَبُو مُعَاذٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[11715,11715,"","তিনি তার সঙ্গে বাইবেল অধ্যয়ন করতে রাজি হয়েছিলেন এবং বাপ্তিস্ম নিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏بَرِيرَةَ ‏ ‏تُصُدِّقَ ‏ ‏عَلَيْهَا ‏ ‏بِصَدَقَةٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَلَنَا هَدِيَّةٌ ‏","","",""],[11716,11716,"","আমরা দুটো জাহাজের কথা বলেছিলাম... ...আমি একজন যাজককে একটা স্যুটের জন্য ডাকতে চাই, আর সে বলবে যে ঈশ্বর কখনো কিছু করেনি.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْقَاسِمُ بْنُ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏ثَعْلَبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏عَجِبْتُ لِلْمُؤْمِنِ إِنَّ اللَّهَ لَمْ يَقْضِ قَضَاءً إِلَّا كَانَ خَيْرًا لَهُ ‏","","",""],[11717,11717,"","তিনি প্রভুর নামে ডাকিনীবিদ্যার ওপর নির্ভর করতেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏هِشَامُ بْنُ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏تُصْبَرَ ‏ ‏الْبَهَائِمُ ‏","","",""],[11718,11718,"","আমরা একটা ছেলের কথা বলেছিলাম যে আপনার টাকা দিয়ে একটা ছেলে যে মাখনের প্রতি ঈর্ষা করে। সে জানে সে জানে সে আপনার ছেলের কাছ থেকে কি পেয়েছে, যে ইতিমধ্যে শুনে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏الزُّبَيْرِ بْنِ عَدِيٍّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَا يَأْتِي عَلَيْكُمْ زَمَانٌ إِلَّا هُوَ شَرٌّ مِنْ الزَّمَانِ الَّذِي كَانَ قَبْلَهُ سَمِعْنَا ذَلِكَ مِنْ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتَيْنِ ‏","","",""],[11719,11719,"","আমরা কয়েক বার কথা বলেছি, আমরা নাকের কথা শুনেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর আমি যতক্ষণ গান গাইতে চাই, ততক্ষণ পর্যন্ত কেউ আমাকে তার মৃত্যু ঘোষণা করেনি। সে বলল, সে ঋণ পরিশোধ করবে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏وَيَعْلَى بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏نَفِيعٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ أَحَدٍ يَوْمَ الْقِيَامَةِ غَنِيٍّ وَلَا فَقِيرٍ إِلَّا وَدَّ أَنَّمَا كَانَ أُوتِيَ مِنْ الدُّنْيَا قُوتًا ‏ ‏قَالَ ‏ ‏يَعْلَى ‏ ‏فِي الدُّنْيَا ‏","","",""],[11720,11720,"","ঈশ্বর আমার কান দিয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ذَا الْأُذُنَيْنِ ‏","","",""],[11721,11721,"","আমরা একটা স্বপ্নের কথা বলেছিলাম, আমার মা কেমন ছিলেন, সেটা নিয়ে স্বপ্নের স্বপ্ন দেখে। সে শান্তি পাবে এবং একজন বার বারবারই তাকে ধরা হবে। ভাল বলতে ইচ্ছুক, শক্তিশালী।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏مَعَ نِسَاءِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُنَّ يَسُوقُ بِهِنَّ سَوَّاقٌ فَأَتَى عَلَيْهِنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَيْ ‏ ‏أَوْ يَا ‏ ‏أَنْجَشَةُ ‏ ‏سَوْقَكَ ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[11722,11722,"","আমি যখন ঘরে ঘরে প্রচার করতাম, তখন আমি আমার সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করি । আমি তোমাকে পৃথিবীর রাজার পাপের হাত থেকে ছিনিয়ে নিচ্ছি.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْعَجْزِ وَالْكَسَلِ ‏ ‏وَالْهَرَمِ ‏ ‏وَالْبُخْلِ وَالْجُبْنِ وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَقَدْ ذَكَرَ فِيهِ الْمَحْيَا وَالْمَمَاتَ ‏","","",""],[11723,11723,"","আমরা যমজদের কথা বলেছিলাম যারা প্রভুর কাছে এমন একজনের সাথে কথা বলেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏عَطَسَ رَجُلَانِ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَمَّتَ ‏ ‏أَوْ ‏ ‏سَمَّتَ ‏ ‏أَحَدَهُمَا فَقَالَ ‏ ‏إِنَّ هَذَا حَمِدَ اللَّهَ عَزَّ وَجَلَّ وَإِنَّ ذَاكَ لَمْ يَحْمَدْ اللَّهَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَرُبَّمَا قَالَ هَذَا أَوْ نَحْوَهُ ‏","","",""],[11724,11724,"","আমি আমার বাবাকে সাহায্য করার চেষ্টা করেছিলাম । তোমার শপথের জন্য দুঃখ, সে করেছে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏لَيَرْضَى عَنْ الْعَبْدِ أَنْ يَأْكُلَ الْأُكْلَةَ أَوْ يَشْرَبَ الشَّرْبَةَ فَيَحْمَدَ اللَّهَ عَزَّ وَجَلَّ ‏ ‏عَلَيْهَا ‏","","",""],[11725,11725,"","আমরা এমন এক নির্দিষ্ট ছেলের কথা বলেছিলাম, যিনি একজন যাজকের কথা বলেছিলেন, যিনি একজন নায়ক ছিলেন । রাজা এটা প্রভুর কাছে নিয়ে এসেছেন, সে পেয়ে গেছে, আর তার জিহ্বা প্রায় জলে ডুবে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ عَامَّةُ وَصِيَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ حَضَرَهُ الْمَوْتُ ‏ ‏الصَّلَاةَ وَمَا مَلَكَتْ أَيْمَانُكُمْ حَتَّى جَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُغَرْغِرُ ‏ ‏بِهَا صَدْرُهُ وَمَا يَكَادُ ‏ ‏يُفِيضُ ‏ ‏بِهَا لِسَانُهُ ‏","","",""],[11726,11726,"","আমরা দুই শতাব্দী ধরে আমার বাবার উপর বিরক্ত হয়ে গেছি, যে কিনা বাবার সাথে ঘোরাফেরা করছিল, ঈশ্বরের প্রার্থনা করবে সে তার কাছে যা পাঠিয়েছে তা তিনি তিন বার যুদ্ধের পর যা করেছেন আগুন লেগে গেছে, অপরাধীদেরকে জিজ্ঞেস করো আমি ভিতরে ঢুকতে দিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏اسْتَجَارَ ‏ ‏عَبْدٌ مِنْ النَّارِ ثَلَاثَ مِرَارٍ إِلَّا قَالَتْ النَّارُ اللَّهُمَّ ‏ ‏أَجِرْهُ ‏ ‏مِنِّي وَلَا يَسْأَلُ الْجَنَّةَ إِلَّا قَالَتْ الْجَنَّةُ اللَّهُمَّ أَدْخِلْهُ إِيَّايَ ‏","","",""],[11727,11727,"","আমরা আমাদের সাহায্য করার কথা বলেছি, যারা বলেছে ঈশ্বর ঈশ্বরকে রক্ষা করেছেন এবং স্বপ্ন দেখছে, কে প্রার্থনা করার আগে চলে গেছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার বন্ধুত্বকে আত্মসমর্পণ করবেন যে আমি আমার হৃদয় থেকে যা ভালোবাসি তা আমি তার কাছে ছেড়ে দিয়েছি, আর সে তার নিজের থেকে নয়, সে চলে গেছে। বন্ধ কর অথবা বলে দাও ওকে ছিঁড়ে ফেল।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏مَنْ كَانَ ذَبَحَ قَبْلَ الصَّلَاةِ فَلْيُعِدْ فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ هَذَا يَوْمٌ ‏ ‏يُشْتَهَى فِيهِ اللَّحْمُ وَذَكَرَ هَنَةً مِنْ جِيرَانِهِ كَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَّقَهُ قَالَ وَعِنْدِي جَذَعَةٌ هِيَ أَحَبُّ إِلَيَّ مِنْ شَاتَيْ لَحْمٍ قَالَ فَرَخَّصَ لَهُ قَالَ ‏ ‏فَلَا أَدْرِي أَبَلَغَتْ رُخْصَتُهُ مَنْ سِوَاهُ أَوْ لَا ‏ ‏قَالَ ثُمَّ انْكَفَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى كَبْشَيْنِ فَذَبَحَهُمَا فَقَامَ النَّاسُ إِلَى غُنَيْمَةٍ فَتَوَزَّعُوهَا ‏ ‏أَوْ قَالَ فَتَجَزَّعُوهَا ‏","","",""],[11728,11728,"","তাকে টাকা নিয়ে যেতে এবং নেতৃত্ব নিতে হবে বলে বলতে হবে আর তারপর আমি এটাকে আগুনের মুখে নিয়ে যাব । তারপর আমি তাকে ঈর্ষার হাত থেকে দূরে সরিয়ে নিয়ে যাই... ...যখন ঈশ্বর তাকে বললেন সে কি করছে, মনে আছে?","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏أَخَذَ ‏ ‏الرَّايَةَ ‏ ‏زَيْدٌ ‏ ‏فَأُصِيبَ ثُمَّ أَخَذَهَا ‏ ‏جَعْفَرٌ ‏ ‏فَأُصِيبَ ثُمَّ أَخَذَهَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏فَأُصِيبَ ثُمَّ أَخَذَهَا ‏ ‏خَالِدٌ ‏ ‏عَنْ غَيْرِ ‏ ‏إِمْرَةٍ ‏ ‏فَفَتَحَ اللَّهُ عَلَيْهِ وَقَالَ مَا يَسُرُّهُمْ ‏ ‏أَوْ قَالَ مَا يَسُرُّنِي ‏ ‏أَنَّهُمْ عِنْدَنَا قَالَ وَإِنَّ عَيْنَيْهِ لَتَذْرِفَانِ ‏","","",""],[11729,11729,"","আমরা প্রেসিডেন্ট সার্জনের কথা বলেছি যে কিনা রাজধানীর প্রধান ছিলেন, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং হলের চোখ আর স্বরের মধ্যে আত্মসমর্পণ করেছেন আমরা যে মারা গেছেন তার জন্য ঈশ্বরের প্রভুর প্রভুর নিকট থেকে একটি রাজধানীর জন্য... ...ঈশ্বরের দোহাই আর ঈশ্বরের দোহাই আছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعُ بْنُ الْجَرَّاحِ الرُّؤَاسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏يُوسُفَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الرُّقْيَةِ ‏ ‏مِنْ الْعَيْنِ ‏ ‏وَالْحُمَةِ ‏ ‏وَالنَّمْلَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[11730,11730,"","আমরা কথা বলেছি এবং ভয় পেয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَعْرٌ ‏ ‏يُصِيبُ ‏ ‏مَنْكِبَيْهِ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏يَضْرِبُ ‏ ‏مَنْكِبَيْهِ ‏","","",""],[11731,11731,"","আমরা একে অপরের সাথে তিন বছরের ঈশ্বরের অনুগ্রহের কথা বলেছি... ...তার কাছে প্রার্থনা করেছেন আর আশ্বস্ত করেছেন যদি তিনি ফেরত না আসেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَزْرَةُ بْنُ ثَابِتٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏ثُمَامَةَ بْنِ عَبْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ بِطِيبٍ لَمْ يَرُدَّهُ ‏","","",""],[11732,11732,"","আমরা আবেগ নিয়ে কথা বলেছি আর যে ফুলগুলো আমি পছন্দ করি সেটা চুরি করে আমি ডাক্তারদের বলেছি। আপনার টাকা বলেছে, নবী তার জন্য প্রার্থনা করছেন আর আমি আপনাকে তার জন্য প্রার্থনা করছি। সমস্ত মুছে ফেলা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَإِسْحَاقُ الْأَزْرَقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَفْطَرَ عِنْدَ أَهْلِ بَيْتٍ قَالَ ‏ ‏أَفْطَرَ عِنْدَكُمْ الصَّائِمُونَ وَأَكَلَ طَعَامَكُمْ الْأَبْرَارُ وَتَنَزَّلَتْ عَلَيْكُمْ الْمَلَائِكَةُ ‏","","",""],[11733,11733,"","আমরা আমার বাবার বাপ্তিস্মের কথা বলেছি... ...যে তোমার টাকা ভুলে গেছে... ...সে একজন ভালো মানুষ, ঈশ্বর তার পতাকা আদেশ করেছেন, আমার ছেলেকে রক্ষা করেছেন, আর সে আমার ছেলে। আমি বলেছিলাম আমরা আর তাকে নিতে পারবো না, আর আল্লাহ্‌ আছে, শেষ জীবিত আছি, সে যা বলেছে তা হলো জয়ের জন্য ক্ষমা করে দেয়া ঈশ্বর, মসজিদের বিল্ডিংটা আমি তাকে প্রার্থনা শেখাই।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ مَوْضِعُ ‏ ‏مَسْجِدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏وَكَانَ فِيهِ نَخْلُ وَقُبُورُ الْمُشْرِكِينَ فَقَالَ لَهُمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَامِنُونِي ‏ ‏بِهِ فَقَالُوا لَا نَأْخُذُ لَهُ ثَمَنًا وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْنِيهِ وَهُمْ يُنَاوِلُونَهُ وَهُوَ يَقُولُ ‏ ‏أَلَا إِنَّ الْعَيْشَ عَيْشُ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏ ‏قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَبْلَ أَنْ ‏ ‏يُبْنَى الْمَسْجِدُ حَيْثُ أَدْرَكَتْهُ الصَّلَاةُ ‏","","",""],[11734,11734,"","আমরা জনপ্রিয়তা আর আমার নেতৃত্বের প্রতি শ্রদ্ধার কথা বলেছি যারা ঈশ্বরকে বলত আমি আমার শান্তি পেয়েছি। আমি পাখির মতো নই আর ভালো কথা বলতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَالدَّسْتُوَائِيِّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏طِيَرَةَ ‏ ‏وَيُعْجِبُنِي الْفَأْلُ قَالَ وَالْفَأْلُ الْكَلِمَةُ الْحَسَنَةُ الطَّيِّبَةُ ‏","","",""],[11735,11735,"","আমরা এই ছেলের কথা বলছি যে ছেলেটির সাথে আমার বাবা আর যখন আমার বাবা, তখন তার সাথে এমন একজন লোকের সাথে কথা বলেছি যে গোপন কথা দেখেছে আর তারপর সে একজন মহিলার অন্ত্যেষ্টিক্রিয়ায় ব্যর্থ হয়েছে আপনি বলেছিলেন, \"আমরা করেছি, \"আমি করেছি,\" বলেছেন, \"আমরা একজন দুঃখিত\"","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏غَالِبٍ ‏ ‏هَكَذَا قَالَ ‏ ‏وَكِيعٌ ‏ ‏غَالِبٍ ‏ ‏وَإِنَّمَا هُوَ ‏ ‏أَبُو غَالِبٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُ أُتِيَ بِجِنَازَةِ رَجُلٍ ‏ ‏فَقَامَ عِنْدَ رَأْسِ السَّرِيرِ ثُمَّ أُتِيَ بِجِنَازَةِ امْرَأَةٍ فَقَامَ أَسْفَلَ مِنْ ذَلِكَ حِذَاءَ السَّرِيرِ فَلَمَّا صَلَّى قَالَ لَهُ ‏ ‏الْعَلَاءُ بْنُ زِيَادٍ ‏ ‏يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏أَهَكَذَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُومُ مِنْ الرَّجُلِ وَالْمَرْأَةِ نَحْوًا مِمَّا رَأَيْتُكَ فَعَلْتَ قَالَ نَعَمْ قَالَ فَأَقْبَلَ عَلَيْنَا ‏ ‏الْعَلَاءُ بْنُ زِيَادٍ ‏ ‏فَقَالَ احْفَظُوا ‏","","",""],[11736,11736,"","আমরা একে অপরের সাথে কথা বলেছি, কিন্তু শুনেছি যে আপনার টাকা ঈশ্বরের জিতে গেছে। আমি আপনাদের মধ্যে এমন একজন কে আছে, যার যৌন সম্পর্ক ছিল। আমরা বললাম যে সে উত্তর দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏سَلَمَةُ بْنُ وَرْدَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَصْحَابِهِ ذَاتَ يَوْمٍ مَنْ شَهِدَ مِنْكُمْ الْيَوْمَ جَنَازَةً قَالَ ‏ ‏عُمَرُ ‏ ‏أَنَا قَالَ مَنْ ‏ ‏عَادَ ‏ ‏مِنْكُمْ مَرِيضًا قَالَ ‏ ‏عُمَرُ ‏ ‏أَنَا قَالَ مَنْ تَصَدَّقَ قَالَ ‏ ‏عُمَرُ ‏ ‏أَنَا قَالَ مَنْ أَصْبَحَ صَائِمًا قَالَ ‏ ‏عُمَرُ ‏ ‏أَنَا قَالَ ‏ ‏وَجَبَتْ وَجَبَتْ ‏","","",""],[11737,11737,"","আমরা এক প্রবল আবেগ কথা বলেছি... ...যার মধ্যে তোমার টাকা ভুলে যাওয়ার কথা ছিল... ...আমি একজন রাজা হওয়ার ভয় পাচ্ছি. ( ১ রাজাবলি ১৮: ১ - ৩) সেই ভাববাদী ঈশ্বরের কাছে প্রার্থনা করেছিলেন, যেন তিনি তার আগে রক্ষা পেয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏أَنْفَجْنَا أَرْنَبًا ‏ ‏بِمَرِّ الظَّهْرَانِ ‏ ‏قَالَ فَسَعَى عَلَيْهَا الْغِلْمَانُ حَتَّى لَغِبُوا قَالَ فَأَدْرَكْتُهَا فَأَتَيْتُ بِهَا ‏ ‏أَبَا طَلْحَةَ ‏ ‏فَذَبَحَهَا ثُمَّ بَعَثَ مَعِي بِوَرِكِهَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَبِلَ ‏","","",""],[11738,11738,"","আমরা কথা বলেছি কিভাবে আমরা সেই লোকদের শাসন করার চেষ্টা করেছি যারা বলেছিল যে নবী আল্লাহকে রক্ষা করেছেন আর চলে গেছেন.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْبَحُ أُضْحِيَّتَهُ بِيَدِهِ ‏","","",""],[11739,11739,"","আমরা অনেক কথা বলেছি, আমার বাবার ছেলের তৃতীয় অংশ হওয়ার কথা, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং জিজ্ঞেস করেছেন যে আমি কার কাছে সবকিছু খরচ করব আর তাকে আমার বুকের মধ্যে ঢুকাতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى الثَّعْلَبِيِّ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَ ‏ ‏الْقَضَاءَ ‏ ‏وُكِلَ إِلَيْهِ وَمَنْ أُجْبِرَ عَلَيْهِ نَزَلَ عَلَيْهِ مَلَكٌ ‏ ‏فَيُسَدِّدُهُ ‏","","",""],[11740,11740,"","আমরা এমন লোকদের জন্য আমার মনোবিজ্ঞানীদের কথা বলেছি যারা ভগবানের কাছে প্রার্থনা করেছে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَشْرَبَ الرَّجُلُ قَائِمًا ‏","","",""],[11741,11741,"","আমরা আমার বাবার রাজধানী নিয়ে একটা আবেগ নিয়ে কথা বলেছি, যার ক্ষমতা ছিল, সে শ্বাস নিচ্ছে এবং বলছে আমি আসলে এটাই।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عِصَامٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَنَفَّسُ فِي الْإِنَاءِ ثَلَاثًا وَيَقُولُ هَذَا أَهْنَأُ ‏ ‏وَأَمْرَأُ ‏ ‏وَأَبْرَأُ ‏","","",""],[11742,11742,"","আমরা কথা বলেছি কিভাবে আমরা বলতে চেষ্টা করেছি যে আমি তোমার কথা শুনতে চাই, \"আমি বলছি না,\" সে তার বোনের ছেলেকে অভিশাপ দিয়েছে তাদের থেকে জেগে ওঠার জন্য। কর.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ قُلْتُ ‏ ‏لِمُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏أَسَمِعْتَ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلنُّعْمَانِ بْنِ مُقَرِّنٍ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ قَالَ نَعَمْ ‏","","",""],[11743,11743,"","আমরা গত দুই মাস ধরে আমার ছেলেকে ঘৃণা করেছি, আপনার টাকা হচ্ছে, নবী তার কাছে প্রার্থনা করেছেন এবং একটি বিকৃত স্বপ্নের মায়ের কাছে প্রবেশ করবেন। এক বলল, \"আমি এক মা একটি মেয়েকে কেটেছি\" সিঁড়ির দিকে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ الْجَزَرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ ابْنَةِ أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏وَفِي الْبَيْتِ ‏ ‏قِرْبَةٌ ‏ ‏مُعَلَّقَةٌ ‏ ‏فَشَرِبَ مِنْ فِيهَا وَهُوَ قَائِمٌ قَالَ فَقَطَعَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏فَمَ ‏ ‏الْقِرْبَةِ ‏ ‏فَهُوَ عِنْدَنَا ‏","","",""],[11744,11744,"","আমরা অনেক বছর ধরে আমার বাবার কাছে কথা বলেছি, আমার বাবার টাকা ভুলে ভালো। লর্ড তার কাছে প্রার্থনা করেছেন এবং তিনি যে কোন ঘুমের জন্য আত্মসমর্পণ করবেন। তাকে উপরে তোল।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أَبَا طَلْحَةَ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَيْتَامٍ وَرِثُوا خَمْرًا فَقَالَ ‏ ‏أَهْرِقْهَا ‏ ‏قَالَ أَفَلَا نَجْعَلُهَا خَلًّا قَالَ لَا ‏","","",""],[11745,11745,"","আমরা দুই গ্রীষ্মের কথা বলেছি... ...যারা ঈশ্বরের দোহাই আর মঙ্গলের জন্য প্রার্থনা করেছে, তারা বলল তুমি আমাকে তোমার বন্ধু হতে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ تَمْرَةً فَقَالَ ‏ ‏لَوْلَا أَنْ تَكُونِي مِنْ ‏ ‏الصَّدَقَةِ ‏ ‏لَأَكَلْتُكِ ‏","","",""],[11746,11746,"","আমরা এমন এক ডাক্তারের কথা বলেছি, যিনি এমন লোকদের নেতৃত্ব দিতে দৃঢ়প্রতিজ্ঞ, যারা ঈশ্বরের দোহাই প্রার্থনা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ حَازِمٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏عَلَى ‏ ‏الْأَخْدَعَيْنِ ‏ ‏وَعَلَى الْكَاهِلِ ‏","","",""],[11747,11747,"","আমরা এক যুবকের জন্য কথা বলেছি যে এটা চেয়েছে আর সে এটা চেয়েছে। সে আগুন থেকে বলেছে যে সে বললো সে কি তার মুখে যা বলেছে, তা দেখে গেছে। আগুন ধরে যাচ্ছিল.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏رَجُلٌ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْنَ أَبِي قَالَ ‏ ‏فِي النَّارِ قَالَ فَلَمَّا رَأَى مَا فِي وَجْهِهِ قَالَ إِنَّ أَبِي وَأَبَاكَ فِي النَّارِ ‏","","",""],[11748,11748,"","আমরা কথা বলেছি এবং তারপর আমরা সুন্নী কন্যাকে সুনজর জন্য জিতেছি। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করেছেন। তিন বছর ধরে তিনি শ্বাস নিচ্ছেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَزْرَةُ بْنُ ثَابِتٍ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ثُمَامَةُ بْنُ عَبْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَنَفَّسُ فِي الْإِنَاءِ ثَلَاثًا ‏","","",""],[11749,11749,"","আমরা অনেক বছর ধরে লর্ড লর্ড লর্ড্সের লর্ড্সের প্রভুর নিকট থেকে বলছি, তাকে চোখের সামনে এবং পর্দার সামনে রাখা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏يُوسُفَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الرُّقْيَةِ ‏ ‏مِنْ الْعَيْنِ وَالنَّمْلَةِ ‏ ‏وَالْحُمَةِ ‏","","",""],[11750,11750,"","আমি শুনেছি যে আমি দুঃখিত, তবে তারা বেড়ে উঠতে বা লুকিয়ে রাখতে পারত।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَصَمِّ ‏ ‏سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَانُوا ‏ ‏يُتِمُّونَ التَّكْبِيرَ فَيُكَبِّرُونَ إِذَا سَجَدُوا وَإِذَا رَفَعُوا ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَوْ خَفَضُوا ‏ ‏قَالَ كَبَّرُوا ‏","","",""],[11751,11751,"","আমরা একটা কলমের সিদ্ধান্তের কথা বলেছিলাম যেটা আমি ভুলবো না, ঈশ্বরের উত্তর তার নিজের আর মিথ্যা বলার জন্য দেয়া হয়েছে মাতাল মানুষ.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُخْتَارَ بْنَ فُلْفُلٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏عَنْ الشُّرْبِ فِي الْأَوْعِيَةِ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُزَفَّتَةِ ‏ ‏وَقَالَ كُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[11752,11752,"","আমরা আপনার টাকা আছে বলে আপনার টাকা নিয়ে বলতে চাই, আপনার টাকা ভুলে যেতে হবে। তিনি শহরের রাস্তা থেকে উদ্ধার করেছেন এবং বলেছেন, \"ঈশ্বর, আমার নাম বলা দরকার, আমার নাম।\" তুমি ঐ রাতে বসেছিলে, সে তার প্রয়োজনের জন্য চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ امْرَأَةً لَقِيَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَرِيقٍ مِنْ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ لِي إِلَيْكَ حَاجَةً قَالَ يَا أُمَّ فُلَانٍ اجْلِسِي فِي أَيِّ نَوَاحِي السِّكَكِ شِئْتِ أَجْلِسْ إِلَيْكِ قَالَ فَقَعَدَتْ ‏ ‏فَقَعَدَ إِلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى قَضَتْ حَاجَتَهَا ‏","","",""],[11753,11753,"","আমরা কথা বলেছি আর বলেছি যে আমরা নিয়ম কানুনের আওতায় আছি, ঈশ্বর তাকে এমন একটা কথা দিয়েছেন যেটা সে প্রস্তুত করেছে","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏عَنْ قِرَاءَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ ‏ ‏يَمُدُّ بِهَا صَوْتَهُ مَدًّا ‏","","",""],[11754,11754,"","আমরা আমার বাবার কথা বলেছি যে আমি তোমার টাকা শুনেছি, সে আমাদের নিচে নামিয়ে দেবে যাতে সে আমাদের ভাই, অনেক পুরানো, সে গান গেয়েছিল। সে এটা পেয়েছে আর আমরা তাকে বর্ণনা করেছি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخَالِطُنَا ‏ ‏حَتَّى يَقُولَ لِأَخٍ لِي صَغِيرٍ يَا ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏ ‏طَائِرٌ كَانَ يَلْعَبُ بِهِ قَالَ ‏ ‏وَنُضِحَ ‏ ‏بِسَاطٌ لَنَا قَالَ فَصَلَّى عَلَيْهِ وَصَفَّنَا خَلْفَهُ ‏","","",""],[11755,11755,"","আমরা অনেক বছর ধরে আমার বাবার অন্ধত্বের কথা বলেছি, সে বলল ঈশ্বর তার জন্য প্রার্থনা করুক আর সে ফোন দিতে চায় না...","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدٍ الْعَمِّيِّ ‏ ‏عَنْ ‏ ‏أَبِي إِيَاسٍ يَعْنِي مُعَاوِيَةَ بْنَ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الدُّعَاءُ لَا يُرَدُّ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ ‏","","",""],[11756,11756,"","আমরা ছেলেটির অনেক কিছু নিয়ে কথা বলেছি, যা সে ভুলে যাওয়ার জন্য অনেক টাকা ভুলে গেছে। সে বলত, ঈশ্বরের বস। তার কাছে তার কাছে নিশ্চয়ই আছে তার কাছে, তার কাছে নিশ্চয়ই চাবির ভেতর থেকে আসা চাবির অনেক কিছুই। তার ফিল্ম.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْزِلُ مِنْ الْمِنْبَرِ يَوْمَ الْجُمُعَةِ فَيُكَلِّمُهُ الرَّجُلُ فِي الْحَاجَةِ فَيُكَلِّمُهُ ثُمَّ يَتَقَدَّمُ إِلَى مُصَلَّاهُ فَيُصَلِّي ‏","","",""],[11757,11757,"","আমরা একটি নির্দিষ্ট আবেগ কথা বলেছি যা এমন একটি সময় শোনা যায় যখন একজন নির্মম আত্মীয়ের ছেলে শুনে। সে বলল, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং একটি ছেলেকে দেবেন। তার চোর থেকে মুক্তি পাবে এবং তার আত্মা রক্ষা পাবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَهْرَمُ ‏ ‏ابْنُ ‏ ‏آدَمَ ‏ ‏وَيَبْقَى مِنْهُ اثْنَتَانِ الْحِرْصُ وَالْأَمَلُ ‏","","",""],[11758,11758,"","আমরা একটি দাঙ্গা সম্পর্কে শুনেছি যে শুনেছি যে আপনি শুনেছেন যে ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি মনে করেন তিনি যখন পারে তিনি তা শুনতে এবং তিনি মনে করবেন,","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَتَّابٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ هُرْمُزَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏بَايَعْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى السَّمْعِ وَالطَّاعَةِ فَقَالَ فِيمَا اسْتَطَعْتُمْ ‏","","",""],[11759,11759,"","আমরা অতিথিকে নিয়ে কথা বলেছি... ...আমি তোমার টাকা না বলতে শুনেছি, এটা ঈশ্বরের কাছে নয়, সে আমাদের আত্মসমর্পণ করতে হবে যদি আমরা বঁড়শির বাইরে থাকি, এমনকি ছায়ার কাছে এসেও না থাকে। নদীটা বলেছে, এটা অর্ধেক নদী।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَمْزَةَ الضَّبِّيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نَزَلَ مَنْزِلًا لَمْ يَرْتَحِلْ حَتَّى يُصَلِّيَ الظُّهْرَ قَالَ فَقَالَ ‏ ‏مُحَمَّدُ بْنُ عُمَرَ ‏ ‏لِأَنَسٍ ‏ ‏يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏وَإِنْ كَانَ بِنِصْفِ النَّهَارِ قَالَ وَإِنْ كَانَ بِنِصْفِ النَّهَارِ ‏","","",""],[11760,11760,"","আমরা বাবার সাথে কথা বলেছি আর ভুলে যাওয়ার জন্য তাকে ধোঁকা দিয়েছি যে সে তার টাকা ভুলে গেছে। আমি উত্তর দিই অথবা আমি তাকে বলি, আমি তাকে বলি যে, আমি যেন তার কাছে কিছু না বলি ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو خُزَيْمَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ رَجُلًا يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ ‏ ‏بِأَنَّ ‏ ‏لَكَ الْحَمْدَ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ ‏ ‏الْمَنَّانَ ‏ ‏بَدِيعَ السَّمَوَاتِ وَالْأَرْضِ ذَا الْجَلَالِ وَالْإِكْرَامِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ سَأَلْتَ اللَّهَ بِاسْمِ اللَّهِ الْأَعْظَمِ الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ وَإِذَا سُئِلَ بِهِ أَعْطَى ‏","","",""],[11761,11761,"","বেনের বয়স বাড়ার ফলে আমরা কথা বলেছি। আমি শুনেছি মানুষ বলেছে আমি ঈশ্বরের কাছে প্রার্থনা করছি। তাকে উদ্ধার করা হয়েছে এবং কখনো ভাড়া করা সম্ভব না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَامِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏احْتَجَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ لَا يَظْلِمُ أَحَدًا أَجْرًا ‏","","",""],[11762,11762,"","আমি একটি ছেলে হারানোর জন্য জীবন অতিবাহিত করার কথা বলছি, আমি একজন স্বপ্নের অধিকারী যে ঈশ্বরের কাছে প্রার্থনা করেছিল সে আমাকে বলবে তিনি আমাকে ১০ নম্বর দিন এবং আপনি তাকে আটকে রেখেছেন আর তুমি তাকে ১০ বছর ধরে নেতৃত্ব দিয়েছ, তারপর আমাকে তোমার প্রয়োজন, সে বলেছে সে হয়ত করবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏جَاءَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ عَلِّمْنِي كَلِمَاتٍ أَدْعُو بِهِنَّ قَالَ ‏ ‏تُسَبِّحِينَ اللَّهَ عَزَّ وَجَلَّ عَشْرًا وَتَحْمَدِينَهُ عَشْرًا وَتُكَبِّرِينَهُ عَشْرًا ثُمَّ سَلِي حَاجَتَكِ فَإِنَّهُ يَقُولُ قَدْ فَعَلْتُ قَدْ فَعَلْتُ ‏","","",""],[11763,11763,"","আমি এর চেয়ে ভালো কিছুর জন্য কথা বলেছি, আল্লাহ তার জন্য প্রার্থনা করেছেন এবং তাকে আত্মসমর্পণ করবেন যে আমি হয়ত দু'টি ভেঙ্গে ফেলেছি এবং আগুনের মত, আগুনের মত, কোন আগুন নেই।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي الْمَاجِشُونَ ‏ ‏عَنْ ‏ ‏صَدَقَةَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏الْنُمَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏قَدْ افْتَرَقَتْ عَلَى اثْنَتَيْنِ وَسَبْعِينَ فِرْقَةً وَأَنْتُمْ تَفْتَرِقُونَ عَلَى مِثْلِهَا كُلُّهَا فِي النَّارِ إِلَّا فِرْقَةً ‏","","",""],[11764,11764,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি, আপনার টাকা ভুলে যাওয়ার কথা ভুলে যাওয়ার ব্যাপারে আমরা সিদ্ধান্ত নিয়েছি। ঈশ্বর তাকে শিখিয়েছেন আর আমার নিজের কোন ক্ষতি হবে না। ভয় না পেয়ে বরং ভয় পাওয়ার জন্য সাহায্য করবে না ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَأُحَدِّثَنَّكُمْ بِحَدِيثٍ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُحَدِّثُكُمْ أَحَدٌ بَعْدِي سَمِعْتُهُ يَقُولُ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَكُونَ فِي الْخَمْسِينَ امْرَأَةً ‏ ‏الْقَيِّمُ ‏ ‏الْوَاحِدُ وَيَكْثُرَ النِّسَاءُ وَيَقِلَّ الرِّجَالُ ‏","","",""],[11765,11765,"","আমরা অনেক বছর ধরে চুপ করে আছি... ...যারা আমাকে বলেছে আমি আমার রাতের বেলা মোশির কাছে যাই, তার আদেশে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَرْتُ لَيْلَةَ أُسْرِيَ بِي عَلَى ‏ ‏مُوسَى ‏ ‏فَرَأَيْتُهُ قَائِمًا ‏ ‏يُصَلِّي فِي قَبْرِهِ ‏","","",""],[11766,11766,"","আমরা একে অপরের বাপ্তিস্মের কথা বলেছি, কিন্তু সে আমাকে বলেছে টাকা নিয়ে ভুলে যেতে। আমাকে আমার পরিবারকে তার কাছে আত্মসমর্পণ করতে হবে। ডানা মানুষকে নির্দোষ হতে বলেছে, আর তারা মারা যেতে পারত।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَرْتُ لَيْلَةَ ‏ ‏أُسْرِيَ ‏ ‏بِي عَلَى قَوْمٍ تُقْرَضُ شِفَاهُهُمْ بِمَقَارِيضَ مِنْ نَارٍ قَالَ قُلْتُ مَنْ هَؤُلَاءِ قَالُوا خُطَبَاءُ مِنْ أَهْلِ الدُّنْيَا كَانُوا يَأْمُرُونَ النَّاسَ بِالْبِرِّ وَيَنْسَوْنَ أَنْفُسَهُمْ وَهُمْ يَتْلُونَ ‏ ‏الْكِتَابَ ‏ ‏أَفَلَا يَعْقِلُونَ ‏","","",""],[11767,11767,"","আমরা একে অপরের বাপ্তিস্মের কথা বলেছি, আপনার টাকা ভুলে গিয়ে... ...ঈশ্বর তার জন্য প্রার্থনা করেছেন, আর আমি ঈশ্বরের কাছে কৃতজ্ঞ। আমি ঈশ্বরের একজন ভয় পাই, রাতে আমার একটা ক্যারিয়ার আছে... ...যা সব কিছু খায় কিন্তু একবারও না, রাতের তিনটা পর পর পর পর।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ ‏ ‏أُوذِيتُ فِي اللَّهِ عَزَّ وَجَلَّ وَمَا ‏ ‏يُؤْذَى أَحَدٌ وَأُخِفْتُ مِنْ اللَّهِ وَمَا يُخَافُ أَحَدٌ وَلَقَدْ أَتَتْ عَلَيَّ ثَلَاثَةٌ مِنْ بَيْنِ يَوْمٍ وَلَيْلَةٍ وَمَا لِي وَلِعِيَالِي طَعَامٌ يَأْكُلُهُ ذُو كَبِدٍ إِلَّا مَا يُوَارِي إِبِطَ ‏ ‏بِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ فِي هَذَا الْحَدِيثِ أَتَتْ عَلَيَّ ثَلَاثُونَ مِنْ بَيْنِ يَوْمٍ وَلَيْلَةٍ ‏","","",""],[11768,11768,"","আমরা কথা বলেছি এটা জিজ্ঞেস করার জন্য। তুমি কাউকে খুব ভালোবাসো। তুমি এমন কি করতে চাও যখন এটা করতে চাও। তাহলে কৌশলটা ভাল এবং ভাল করে করতে হবে। তাহলে সে এটা করতে পারবে, সে কিছু করার আগেই ঠিক কাজ করবে, তারপর সে তাকে চুমু দেবে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا عَلَيْكُمْ أَنْ لَا تَعْجَبُوا بِأَحَدٍ حَتَّى تَنْظُرُوا بِمَ يُخْتَمُ لَهُ ‏ ‏فَإِنَّ الْعَامِلَ يَعْمَلُ زَمَانًا مِنْ عُمْرِهِ أَوْ بُرْهَةً مِنْ دَهْرِهِ بِعَمَلٍ صَالِحٍ لَوْ مَاتَ عَلَيْهِ دَخَلَ الْجَنَّةَ ثُمَّ يَتَحَوَّلُ فَيَعْمَلُ عَمَلًا سَيِّئًا وَإِنَّ الْعَبْدَ لَيَعْمَلُ الْبُرْهَةَ مِنْ دَهْرِهِ بِعَمَلٍ سَيِّئٍ لَوْ مَاتَ عَلَيْهِ دَخَلَ النَّارَ ثُمَّ يَتَحَوَّلُ فَيَعْمَلُ عَمَلًا صَالِحًا وَإِذَا أَرَادَ اللَّهُ بِعَبْدٍ خَيْرًا اسْتَعْمَلَهُ قَبْلَ مَوْتِهِ قَالُوا يَا رَسُولَ اللَّهِ وَكَيْفَ يَسْتَعْمِلُهُ قَالَ يُوَفِّقُهُ لِعَمَلٍ صَالِحٍ ثُمَّ يَقْبِضُهُ عَلَيْهِ ‏","","",""],[11769,11769,"","তিনি গরু ও দুই বছর বয়সী সেই ব্যক্তি ছিলেন আর সেই ব্যক্তি ছিলেন সেই ব্যক্তি যিনি চুল ও দুই বার দেখেছিলেন । আমার কাছে প্রার্থনা এবং সালামকে তার নিজের স্কুলে যেতে হবে । আর আমি যখন তোমাকে বলেছিলাম আমি কিভাবে বলছি যে আমি কত জোরে যেতে যাচ্ছি, তখন সিঁড়িতে শয়তান ধরা পড়ে। আমি জানতাম তুমি অদ্ভুত ছিলে... ...সেই-ই যে ছিল সেই সেই-ই যে-ই সে-ই সে-ই। তিনিই সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি আপনাকে ছেড়ে দিতে হবে। তাকে কিস করেনি আর বলেছে যে মাত্র দুইজন আমাকে বলেছে যে সে ভুল করতে পারবে না। কিন্তু আমার ভাগের মতই আমরা এমন লোকদের সাথে আছি যারা তার লেখা লিখেছে। গরু আর দুটো হল সবচেয়ে বড় অপরাধী ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَجُلًا كَانَ يَكْتُبُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ كَانَ قَرَأَ ‏ ‏الْبَقَرَةَ ‏ ‏وَآلَ ‏ ‏عِمْرَانَ ‏ ‏وَكَانَ الرَّجُلُ إِذَا قَرَأَ ‏ ‏الْبَقَرَةَ ‏ ‏وَآلَ ‏ ‏عِمْرَانَ ‏ ‏جَدَّ فِينَا ‏ ‏يَعْنِي عَظُمَ ‏ ‏فَكَانَ النَّبِيُّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏يُمْلِي عَلَيْهِ غَفُورًا رَحِيمًا فَيَكْتُبُ عَلِيمًا حَكِيمًا فَيَقُولُ لَهُ النَّبِيُّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏اكْتُبْ كَذَا وَكَذَا اكْتُبْ كَيْفَ شِئْتَ ‏ ‏وَيُمْلِي عَلَيْهِ عَلِيمًا حَكِيمًا فَيَقُولُ أَكْتُبُ سَمِيعًا بَصِيرًا فَيَقُولُ اكْتُبْ اكْتُبْ كَيْفَ شِئْتَ فَارْتَدَّ ذَلِكَ الرَّجُلُ عَنْ الْإِسْلَامِ فَلَحِقَ بِالْمُشْرِكِينَ وَقَالَ أَنَا أَعْلَمُكُمْ ‏ ‏بِمُحَمَّدٍ ‏ ‏إِنْ كُنْتُ لَأَكْتُبُ مَا شِئْتُ فَمَاتَ ذَلِكَ الرَّجُلُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْأَرْضَ لَمْ تَقْبَلْهُ ‏ ‏و قَالَ ‏ ‏أَنَسٌ ‏ ‏فَحَدَّثَنِي ‏ ‏أَبُو طَلْحَةَ ‏ ‏أَنَّهُ أَتَى الْأَرْضَ الَّتِي مَاتَ فِيهَا ذَلِكَ الرَّجُلُ فَوَجَدَهُ ‏ ‏مَنْبُوذًا ‏ ‏فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏مَا شَأْنُ هَذَا الرَّجُلِ قَالُوا قَدْ دَفَنَّاهُ مِرَارًا فَلَمْ تَقْبَلْهُ الْأَرْضُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ السَّهْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ يَكْتُبُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ قَرَأَ ‏ ‏الْبَقَرَةَ ‏ ‏وَآلَ ‏ ‏عِمْرَانَ ‏ ‏وَكَانَ الرَّجُلُ إِذَا قَرَأَ ‏ ‏الْبَقَرَةَ ‏ ‏وَآلَ ‏ ‏عِمْرَانَ ‏ ‏يُعَدُّ فِينَا عَظِيمًا فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏يَزِيدَ ‏","","",""],[11770,11770,"","আমরা আপনার টাকা ভুলে আমাদের এক ছেলের কথা বলছি, আমি একটি ভাল বিয়েতে বাবাকে একটা গুলি করে দেবো... ...সে আমাকে ভগবান বলে ডাকে আর সে তোমার ঘোড়া শেষ করে দেবে। আমি তোমার টাকা রেখে দিয়েছি। ভাগ্য.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا طَلْحَةَ ‏ ‏فِي غَزْوَةِ ‏ ‏خَيْبَرَ ‏ ‏يُنَادِي ‏ ‏إِنَّ اللَّهَ وَرَسُولَهُ يَنْهَيَانِكُمْ عَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ فَإِنَّهَا ‏ ‏رِجْسٌ ‏ ‏قَالَ ‏ ‏فَأُكْفِئَتْ ‏ ‏الْقُدُورُ ‏","","",""],[11771,11771,"","আমরা হারুনের মধ্যে আছি... ...আমাদের বাবা বাক এর সাথে কথা বলেছি... ...যখন আমরা আমার কাজ শেষ করেছি, ঈশ্বর তাকে আদেশ দিয়েছেন আর আত্মসমর্পণ করেছেন। আমি যখন বলেছি যে ঈশ্বর এটা দিয়েছেন এবং আমাকে জিজ্ঞাসা করেছেন, কিন্তু আমি কথা বলেছি। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏وَعَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَنَادَى رَجُلٌ رَجُلًا يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَالْتَفَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ الرَّجُلُ لَمْ أَعْنِكَ يَا رَسُولَ اللَّهِ إِنَّمَا عَنَيْتُ فُلَانًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏فِي حَدِيثِهِ تَسَمَّوْا بِاسْمِي ‏","","",""],[11772,11772,"","আমরা তাদের কথা বলেছি যারা আল্লাহ আছে এবং তাদের দয়া করুন। রাতভর রাত পার হয়ে গেছে। তাই তিনি বোমা হামলা করেন এবং তারপর তিনি দিনের সেরা কাজটি করেন। তারপর তিনি প্রার্থনা করেন যেন তিনি প্রার্থনা করেন। মানুষ বলেছে সে কেমন ছিল, আর মারা যাওয়ার সময় সেটাই ছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلَهُ رَجُلٌ عَنْ وَقْتِ صَلَاةِ الصُّبْحِ ‏ ‏فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ حِينَ طَلَعَ الْفَجْرُ ثُمَّ أَقَامَ فَصَلَّى فَلَمَّا كَانَ مِنْ الْغَدِ أَخَّرَ حَتَّى ‏ ‏أَسْفَرَ ‏ ‏ثُمَّ أَمَرَهُ أَنْ يُقِيمَ فَصَلَّى ثُمَّ دَعَا الرَّجُلَ فَقَالَ مَا بَيْنَ هَذَا وَهَذَا وَقْتٌ ‏","","",""],[11773,11773,"","আমরা যারা আমাকে ফোন করেছে তাদের কথা বলছি, ঈশ্বর আমাকে জিজ্ঞেস করেছেন, তোমার মত ঈশ্বরও কিছু একটা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ مِنْ دُعَاءِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏اللَّهُمَّ إِنْ شِئْتَ أَنْ لَا تُعْبَدَ بَعْدَ الْيَوْمِ ‏","","",""],[11774,11774,"","আমরা তিনজন মানুষ কথা বলেছি যারা ঈশ্বরকে পাঠিয়েছে, তাদেরকে সব করতে বলা হয়েছে, সে ছেলেদের সাথে খেলা করে তার হৃদয়ের মধ্যে নিয়ে যায়। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাঁকে আত্মসমর্পণ করার জন্য প্রার্থনা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَلْعَبُ مَعَ الصِّبْيَانِ فَأَتَاهُ آتٍ فَأَخَذَهُ فَشَقَّ ‏ ‏صَدْرَهُ ‏ ‏فَاسْتَخْرَجَ مِنْهُ ‏ ‏عَلَقَةً ‏ ‏فَرَمَى بِهَا وَقَالَ هَذِهِ نَصِيبُ الشَّيْطَانِ مِنْكَ ثُمَّ غَسَلَهُ فِي طَشْتٍ مِنْ ذَهَبٍ مِنْ مَاءِ ‏ ‏زَمْزَمَ ‏ ‏ثُمَّ لَأَمَهُ فَأَقْبَلَ الصِّبْيَانُ إِلَى ‏ ‏ظِئْرِهِ ‏ ‏قُتِلَ ‏ ‏مُحَمَّدٌ ‏ ‏قُتِلَ ‏ ‏مُحَمَّدٌ ‏ ‏فَاسْتَقْبَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ انْتَقَعَ لَوْنُهُ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَلَقَدْ كُنَّا نَرَى أَثَرَ الْمَخِيطِ فِي صَدْرِهِ ‏","","",""],[11775,11775,"","আমরা অনেক বেশি কথা বলেছি, হ্যাপি এন্ড সন এর পুত্র বলেছেন আমরা আনন্দের সাথে তোমাকে উপভোগ করতে চাই। যে মহিলা তার ঘুমের মধ্যে দেখেছেন তাকে নিজের শান্তি দিতে হবে, যদি সে মারা যায়। অথবা খারাপ কিছু.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ امْرَأَةٍ ‏ ‏تَرَى فِي مَنَامِهَا مَا يَرَى الرَّجُلُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَأَتْ ذَلِكَ مِنْكُنَّ فَأَنْزَلَتْ فَلْتَغْتَسِلْ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏أَوَ يَكُونُ ذَلِكَ يَا رَسُولَ اللَّهِ قَالَ نَعَمْ مَاءُ الرَّجُلِ غَلِيظٌ أَبْيَضُ وَمَاءُ الْمَرْأَةِ أَصْفَرُ رَقِيقٌ فَأَيُّهُمَا سَبَقَ أَوْ عَلَا أَشْبَهَهُ الْوَلَدُ ‏","","",""],[11776,11776,"","আমরা আমাদের বলতে চাই যে কেউ সুখী হতে পারে আমি আর আমি তাদের কাছে কসম কেটে বলছি আমি আপনার টাকা নিয়ে চলে যাব. আমি যে শিক্ষককে বলছি আপনি খুশি মনে আমি আপনাকে খুশি মনে করছি সে চলে গেছে, আর তারপর সে তার বার্তাবাহককে তার কাছে প্রার্থনা করলো আর তার মুখ থেকে খেতে দিল, ঈশ্বর একটা কাটিরা থেকে খাবার দিলেন যেটা প্রভুর অনুগ্রহে এসেছে। তার ইচ্ছা, অথবা অবস্থানের অনুপ্রেরণা কোন কথা বলে নি এবং এরপর তিনি মানুষকে এই অনুপ্রেরণা দেবার জন্য এগিয়ে যান, তাকে আত্মসমর্পণ করতে হবে, এবং তারা তাকে ভালবাসবে, তারা হবে। আমাদের আর দেখা হবে না, তোমার চেয়ে পাগল হয়ে যাওয়া।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏وَاقِدُ بْنُ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَكَانَ ‏ ‏وَاقِدٌ ‏ ‏مِنْ أَحْسَنِ النَّاسِ وَأَعْظَمِهِمْ وَأَطْوَلِهِمْ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏فَقَالَ لِي مَنْ أَنْتَ قُلْتُ أَنَا ‏ ‏وَاقِدُ بْنُ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ ‏ ‏قَالَ إِنَّكَ ‏ ‏بِسَعْدٍ ‏ ‏أَشْبَهُ ثُمَّ بَكَى وَأَكْثَرَ الْبُكَاءَ فَقَالَ رَحْمَةُ اللَّهِ عَلَى ‏ ‏سَعْدٍ ‏ ‏كَانَ مِنْ أَعْظَمِ النَّاسِ وَأَطْوَلِهِمْ ثُمَّ قَالَ بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَيْشًا إِلَى ‏ ‏أُكَيْدِرَ ‏ ‏دُومَةَ ‏ ‏فَأَرْسَلَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجُبَّةٍ ‏ ‏مِنْ ‏ ‏دِيبَاجٍ ‏ ‏مَنْسُوجٍ فِيهِ الذَّهَبُ فَلَبِسَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ عَلَى الْمِنْبَرِ ‏ ‏أَوْ جَلَسَ ‏ ‏فَلَمْ يَتَكَلَّمْ ثُمَّ نَزَلَ فَجَعَلَ النَّاسُ يَلْمِسُونَ ‏ ‏الْجُبَّةَ ‏ ‏وَيَنْظُرُونَ إِلَيْهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَعْجَبُونَ مِنْهَا قَالُوا مَا رَأَيْنَا ثَوْبًا قَطُّ أَحْسَنَ ‏ ‏مِنْهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَنَادِيلُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏فِي الْجَنَّةِ أَحْسَنُ مِمَّا تَرَوْنَ ‏","","",""],[11777,11777,"","আমরা একটা ছেলের কথা বলেছি যে একজন যাজকের চেয়ে ভাল, ঈশ্বর তার জন্য প্রার্থনা করেন এবং তার নিজের জন্য একটি ছবি তুলেন। তিনি বলেছিলেন, একবার তিনি আমাকে ঈশ্বরের মেয়েদের কাছে এই কথা বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَهْدَى ‏ ‏الْأُكَيْدِرُ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَرَّةً مِنْ ‏ ‏مَنٍّ ‏ ‏فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الصَّلَاةِ ‏ ‏مَرَّ عَلَى الْقَوْمِ فَجَعَلَ يُعْطِي كُلَّ رَجُلٍ مِنْهُمْ قِطْعَةً فَأَعْطَى ‏ ‏جَابِرًا ‏ ‏قِطْعَةً ثُمَّ إِنَّهُ رَجَعَ إِلَيْهِ فَأَعْطَاهُ قِطْعَةً أُخْرَى فَقَالَ إِنَّكَ قَدْ أَعْطَيْتَنِي مَرَّةً قَالَ هَذَا لِبَنَاتِ ‏ ‏عَبْدِ اللَّهِ ‏","","",""],[11778,11778,"","আমরা বাবার বয়স পার হওয়ার কথা বলেছিলাম, সে কিভাবে করেছে সেটা নিয়ে তাকে ফিরে যেতে বলা উচিত, ঈশ্বর তাকে একটা মই দিতে হবে, তিনি পরের আকাশ থেকে আবার আকাশের দিকে ফিরে যাবেন বেদনা আর হতাশা।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَعَوَّذُ مِنْ ثَمَانٍ الْهَمِّ ‏ ‏وَالْحَزَنِ ‏ ‏وَالْعَجْزِ وَالْكَسَلِ وَالْبُخْلِ وَالْجُبْنِ وَغَلَبَةِ الدَّيْنِ وَغَلَبَةِ الْعَدُوِّ ‏","","",""],[11779,11779,"","আমাদের অভিজ্ঞতার কথা হল, যখন ঈশ্বর তাকে উদ্ধার করেছেন, তখন তিনি আমাদের একজন প্রভু হওয়ার অভিজ্ঞতা লাভ করেছেন। একমাত্র কারণ আমরা তোমার মনের উপর হারিয়ে ফেলেছি। আমাকে অনুমান করতে হবে যে ঈশ্বর এখানে আছেন কিন্তু আমি তা করতে পারবো না, অপরাধ স্বীকারকারীদের জন্য তাদের সময় আলাদা করে রাখা হয় এবং তাদের রক্ষা করা হয়।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُ عَلَيْكَ وَيَهْدِيَكَ صِرَاطًا مُسْتَقِيمًا ‏} ‏قَالَ الْمُسْلِمُونَ يَا رَسُولَ اللَّهِ هَنِيئًا لَكَ مَا أَعْطَاكَ اللَّهُ فَمَا لَنَا فَنَزَلَتْ ‏ { ‏لِيُدْخِلَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ ‏ ‏تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّئَاتِهِمْ وَكَانَ ذَلِكَ عِنْدَ اللَّهِ فَوْزًا عَظِيمًا ‏}","","",""],[11780,11780,"","আমরা ঐ ছেলের কথা অনেক আগে বলেছি... ...যখন রবিবার পরাজিত হল, তখন সে বলল, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর আমি তাকে আত্মসমর্পণ করবো তারপর তার কাছে আমি এই স্লিপিংটা নিয়ে যাই এবং আমি মনে করি তারা আপনার সাথে কি করতে হবে। সে বলল আমি মক্কা থেকে ঘুমাতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏هَبَطَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابِهِ ثَمَانُونَ رَجُلًا مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏فِي السِّلَاحِ مِنْ قِبَلِ ‏ ‏جَبَلِ التَّنْعِيمِ ‏ ‏فَدَعَا عَلَيْهِمْ فَأُخِذُوا وَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَهُوَ الَّذِي كَفَّ أَيْدِيَهُمْ عَنْكُمْ وَأَيْدِيَكُمْ عَنْهُمْ بِبَطْنِ ‏ ‏مَكَّةَ ‏ ‏مِنْ بَعْدِ أَنْ ‏ ‏أَظْفَرَكُمْ ‏ ‏عَلَيْهِمْ ‏} ‏قَالَ ‏ ‏يَعْنِي ‏ ‏جَبَلَ التَّنْعِيمِ ‏ ‏مِنْ ‏ ‏مَكَّةَ ‏","","",""],[11781,11781,"","আমরা একজন শাসক হওয়া সম্পর্কে কথা বলেছি মানুষ সম্পর্কে আমি শুনেছি, সে বলল যে আমরা এমন কিছু জানি যা আমাদের নিচে যেতে হবে অথবা সে বলে যে একটি ছেলে মারা যাবে. যে ভগবানকে ছেড়ে দিতে চায়নি, তার উত্তর কি?","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَسْمَعُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فَلَا أَدْرِي أَشَيْءٌ نَزَلَ عَلَيْهِ أَمْ شَيْءٌ يَقُولُهُ وَهُوَ يَقُولُ ‏ ‏لَوْ كَانَ لِابْنِ ‏ ‏آدَمَ ‏ ‏وَادِيَانِ مِنْ مَالٍ لَابْتَغَى لَهُمَا ثَالِثًا وَلَا يَمْلَأُ جَوْفَ ابْنِ ‏ ‏آدَمَ ‏ ‏إِلَّا التُّرَابُ وَيَتُوبُ اللَّهُ عَلَى مَنْ تَابَ ‏","","",""],[11782,11782,"","আমরা তোমার টাকা হারানোর কথা বলেছি, সে তাদের কাছে আত্মসমর্পণ করেছে","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَتْ نِعَالُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَهُمَا قِبَالَانِ ‏","","",""],[11783,11783,"","আমরা আমাদের সংবাদের চেয়ে অনেক বেশি কথা বলেছি। এর মানে হচ্ছে ভালো লোকদের জন্য বেঁচে থাকা একটা ছেলে, আল্লাহকে তার শান্তি ফিরিয়ে আনতে বলা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ يَعْنِي ابْنَ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏الزُّبَيْرَ بْنَ الْعَوَّامِ ‏ ‏وَعَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏شَكَوَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقَمْلَ فَرَخَّصَ لَهُمَا فِي لُبْسِ الْحَرِيرِ فَرَأَيْتُ عَلَى كُلِّ وَاحِدٍ مِنْهُمَا قَمِيصًا مِنْ حَرِيرٍ ‏","","",""],[11784,11784,"","আমরা ঈশ্বর এসে এসব বলতে সক্ষম হওয়ার ব্যাপারে অনেক কথা বলেছি, প্রার্থনা, মিছিল শ্রেণী।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ حُسْنِ الصَّلَاةِ إِقَامَةَ الصَّفِّ ‏","","",""],[11785,11785,"","আমরা আমার বাবার বয়স যুগ যুগ সম্পর্কে কথা বলেছি যারা বলেছে ভুলে যাওয়ার সময়, ঈশ্বরকে শারপ গল্পে আত্মসমর্পণ করতে হবে এবং বলে রাখি ছায়ার ছায়ার আড়ালে। প্রতি কোয়ার্টারে অভিশাপ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏صَدَقَةُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏وَقَّتَ ‏ ‏لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَصِّ الشَّارِبِ وَتَقْلِيمِ الْأَظْفَارِ وَحَلْقِ الْعَانَةِ فِي كُلِّ أَرْبَعِينَ يَوْمًا مَرَّةً ‏","","",""],[11786,11786,"","আমরা একজন নেতা হওয়ার কথা বলেছি, ঈশ্বর তার শান্তি রক্ষা করেছেন বলে আমি দুঃখিত, যখন আমি ক্লান্ত হয়ে গেছি, তখন আমার কাছে যেতে চাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَبُّكُمْ عَزَّ وَجَلَّ ‏ ‏إِنْ تَقَرَّبَ عَبْدِي مِنِّي شِبْرًا تَقَرَّبْتُ مِنْهُ ذِرَاعًا وَإِنْ تَقَرَّبَ مِنِّي ذِرَاعًا تَقَرَّبْتُ مِنْهُ بَاعًا وَإِنْ أَتَانِي مَاشِيًا أَتَيْتُهُ هَرْوَلَةً ‏","","",""],[11787,11787,"","আমরা একজন যাজকের ছেলেকে তৈরি করতে বলেছিলাম যে কখনো যুদ্ধবাজ হয়নি, ঈশ্বর তাকে আদেশ দিয়েছেন আর সে এত ভাল যে সে মারা গেছে, সে কি হবে? আমরা শহর থেকে এসেছি যাদের দেখে আমার বাবা আর ভয় পাওয়া যায়। যদি আমরা নিরাপদ থাকি, আমরা নিরাপদ থাকি, \"আমি একজন মানুষ,\" যখন সে তাকে এতিম দেখতে পেল, অথবা আমি তার থেকে ভালো হতে পারবো না। আমি শহর ছেড়ে চলে যাব এবং আমি যখন দেখি তখন তার মুখ দেখে আসি, ঈশ্বর তাকে উদ্ধার করেছেন। আমি নিশ্চিত নই, আমি জানি, ঈশ্বর তাকে উদ্ধার করেছেন। এবং তাঁর চেহারা দেখে রাখুন, আমি নিশ্চিত নই যে, আমি এই শহরে বাস করি, আমি তার মুখ দেখতে পাব। এবং আমি তাকে দেখতে চাই, আমি আমার মনের কথা বলি, আমি যেন আমি আমার মনের কথা বলি। এবং আমি তাকে বলি, আমি আমার মনের কথা বলি। আমি যখন আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, ঈশ্বর আমাদের জীবন পরিবর্তন করতে হবে। এবং আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি জানি, ঈশ্বর আমাদের জীবন দান করেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا هَاجَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْكَبُ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏رَدِيفُهُ ‏ ‏وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يُعْرَفُ فِي الطَّرِيقِ لِاخْتِلَافِهِ إِلَى ‏ ‏الشَّامِ ‏ ‏وَكَانَ يَمُرُّ بِالْقَوْمِ فَيَقُولُونَ مَنْ هَذَا بَيْنَ يَدَيْكَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَيَقُولُ هَادٍ يَهْدِينِي فَلَمَّا دَنَوْا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏بَعَثَ إِلَى الْقَوْمِ الَّذِينَ أَسْلَمُوا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِلَى ‏ ‏أَبِي أُمَامَةَ ‏ ‏وَأَصْحَابِهِ فَخَرَجُوا إِلَيْهِمَا فَقَالُوا ادْخُلَا آمِنَيْنِ مُطَاعَيْنِ فَدَخَلَا ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَمَا رَأَيْتُ يَوْمًا قَطُّ أَنْوَرَ وَلَا أَحْسَنَ مِنْ يَوْمِ دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏الْمَدِينَةَ ‏ ‏وَشَهِدْتُ وَفَاتَهُ فَمَا رَأَيْتُ يَوْمًا قَطُّ أَظْلَمَ وَلَا أَقْبَحَ مِنْ الْيَوْمِ الَّذِي تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ ‏","","",""],[11788,11788,"","আমরা কথা বলেছি আমরা যারা তিন বছর ধরে বাপ্তিস্ম নিয়েছে তাদের খুঁজে বের করার ব্যাপারে। আমি ভুলে গেছি তার জন্য প্রার্থনা করে যাচ্ছি এবং সে যা করেছে তা নিয়ে অনেক বেশি কথা বলেছি। যে এটা নেবে তাকে হত্যা করবে, তারা তাকে দেখছে কে তাকে নিয়ে যাচ্ছে, যে তাকে নিয়ে যাচ্ছে, সে শপথ নিয়েছে যে সে জেলে আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَعَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ سَيْفًا يَوْمَ ‏ ‏أُحُدٍ ‏ ‏فَقَالَ مَنْ يَأْخُذُ هَذَا السَّيْفَ فَأَخَذَهُ قَوْمٌ فَجَعَلُوا يَنْظُرُونَ إِلَيْهِ فَقَالَ مَنْ يَأْخُذُهُ بِحَقِّهِ ‏ ‏فَأَحْجَمَ ‏ ‏الْقَوْمُ فَقَالَ ‏ ‏أَبُو دُجَانَةَ سِمَاكٌ ‏ ‏أَنَا آخُذُ بِحَقِّهِ فَأَخَذَهُ فَفَلَقَ ‏ ‏هَامَ ‏ ‏الْمُشْرِكِينَ ‏","","",""],[11789,11789,"","আমাদের বলা হয়েছে হামাদের কথা কিন্তু তোমার নামে আমার বাবা শপথ নিয়েছে যে, ঈশ্বর তার জন্য প্রার্থনা করেছেন, আর সে একজন মানুষের মৃত্যুর জন্য আত্মসমর্পণ করবে যে কিনা ব্যর্থ হয়েছে। তাকে মরতে দাও, আমি তাদের জিজ্ঞেস করছি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏مَنْ قَتَلَ رَجُلًا فَلَهُ ‏ ‏سَلَبُهُ ‏ ‏فَقَتَلَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏عِشْرِينَ رَجُلًا فَأَخَذَ ‏ ‏أَسْلَابَهُمْ ‏","","",""],[11790,11790,"","আমরা কিভাবে আরো ভাল করার চেষ্টা করেছি আমরা কথা বলেছি। আমি আপনাদের টাকা ভুলে গেছি যে ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন তাকে দোষারোপ করা হবে না। শেষ পর্যন্ত এটা পাওয়া যায়, অথবা এটা তার জন্য উপযুক্ত। আমরা কি করে বলছি, যদি আমরা এটা করতে পারি? আমরা কি করে এর জন্য চেষ্টা করেছি? আমি জানি, আমরা কি করে, আমরা এটা করেছি? আমি জানি না যে, আমরা কি করে বলছি, আমরা এটা করতে পারি, আমরা কি করে, আমরা এটা করেছি? আমি জানি, আমরা কি করেছি? আমি যদি এটা নিতে চাই, তাহলে ঋণ শোধ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَبَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَا يَظْلِمُ الْمُؤْمِنَ حَسَنَةً يُعْطَى عَلَيْهَا فِي الدُّنْيَا وَيُثَابُ عَلَيْهَا فِي الْآخِرَةِ وَأَمَّا الْكَافِرُ ‏ ‏فَيُعْطِيهِ حَسَنَاتِهِ فِي الدُّنْيَا حَتَّى إِذَا ‏ ‏أَفْضَى ‏ ‏إِلَى الْآخِرَةِ لَمْ يَكُنْ لَهُ بِهَا حَسَنَةٌ يُعْطَى بِهَا خَيْرًا ‏","","",""],[11791,11791,"","আমরা ঈশ্বরের ছেলের কথা বলেছি... ...সে তার টাকা ভুলে গেছে, তাকে আত্মসমর্পণ করবে, তারপর তাকে তুলে নিয়ে যাবে, আর তারপর সে বললো, সে মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ أَصَابِعَهُ فَوَضَعَهَا عَلَى الْأَرْضِ فَقَالَ هَذَا ابْنُ ‏ ‏آدَمَ ‏ ‏ثُمَّ رَفَعَهَا خَلْفَ ذَلِكَ قَلِيلًا وَقَالَ هَذَا أَجَلُهُ ثُمَّ رَمَى بِيَدِهِ أَمَامَهُ قَالَ وَثَمَّ أَمَلُهُ ‏","","",""],[11792,11792,"","আমরা আপনার টাকা ভুলে যাওয়া ছেলের সম্পর্কে কথা বলেছি, সে তার শান্তির কথা ভুলে গেছে, যদি সে তার চেহারার সাথে জড়িত থাকে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا دَعَا جَعَلَ ظَاهِرَ كَفَّيْهِ مِمَّا يَلِي وَجْهَهُ وَبَاطِنَهُمَا مِمَّا ‏ ‏يَلِي ‏ ‏الْأَرْضَ ‏","","",""],[11793,11793,"","আমরা অনেক কথা বলেছি, আমরা ছেলেটির কথা ভুলে যাওয়ার কথা ভুলে গিয়ে তোমার টাকা নিয়ে ভুলে গেছি। আমার কুকুরের প্রবৃত্তি হচ্ছে, ঈশ্বর একটি প্রান্তরে পড়ে গেছেন। সে ছিল বহু বছর আগে, সে ছিল। আমি তাকে বিয়ে করার জন্য বিয়ে করবো, নাকি তার দাস তাকে বিয়ে করবে, সে যখন বিয়ে করবে, তখন সে তাকে বিয়ে করবে। তার শহর ঋণ করে অথবা মানুষকে ঈশ্বরের কাছে প্রার্থনা করতে হয়। মুখটা দেখে মনে হচ্ছে ঈশ্বরের কাছে যাওয়ার পর সে এটা করেছে। আমরা বলেছিলাম, এক গ্রীষ্মে কিছু টাকা আছে। তার নাম বলতে গেলে সে কিছু বলতে পারেনি যে সে নিজেই তৈরি করেছে। তার চোখ, তারপর সে আমাকে আঘাত করেছে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏صَفِيَّةَ ‏ ‏وَقَعَتْ فِي سَهْمِ ‏ ‏دِحْيَةَ الْكَلْبِيِّ ‏ ‏فَقِيلَ يَا رَسُولَ اللَّهِ قَدْ وَقَعَتْ فِي سَهْمِ ‏ ‏دِحْيَةَ ‏ ‏جَارِيَةٌ جَمِيلَةٌ ‏ ‏فَاشْتَرَاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَبْعَةِ أَرْؤُسٍ فَجَعَلَهَا عِنْدَ ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏حَتَّى تَهَيَّأَ ‏ ‏وَتَعْتَدَّ ‏ ‏فِيمَا يَعْلَمُ ‏ ‏حَمَّادٌ ‏ ‏فَقَالَ النَّاسُ وَاللَّهِ مَا نَدْرِي أَتَزَوَّجَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ تَسَرَّاهَا فَلَمَّا حَمَلَهَا سَتَرَهَا وَأَرْدَفَهَا خَلْفَهُ فَعَرَفَ النَّاسُ أَنَّهُ قَدْ تَزَوَّجَهَا فَلَمَّا دَنَا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏أَوْضَعَ ‏ ‏النَّاسُ ‏ ‏وَأَوْضَعَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَذَلِكَ كَانُوا يَصْنَعُونَ فَعَثَرَتْ النَّاقَةُ ‏ ‏فَخَرَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَرَّتْ مَعَهُ وَأَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْظُرْنَ فَقُلْنَ أَبْعَدَ اللَّهُ الْيَهُودِيَّةَ وَفَعَلَ بِهَا وَفَعَلَ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَتَرَهَا وَأَرْدَفَهَا خَلْفَهُ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَارَتْ ‏ ‏صَفِيَّةُ ‏ ‏لِدِحْيَةَ ‏ ‏فِي قَسْمِهِ فَذَكَرَ نَحْوَهُ إِلَّا أَنَّهُ قَالَ حَتَّى إِذَا جَعَلَهَا فِي ظَهْرِهِ نَزَلَ ثُمَّ ضَرَبَ عَلَيْهَا ‏ ‏الْقُبَّةَ ‏","","",""],[11794,11794,"","ঈশ্বর চুলার ছেলে স্টর্সের ছেলে, তার হৃদয়ের ভিতরে এবং কবর দিয়ে বেরিয়েছিল সে আমাকে মূল্য দেবে আর বলবে যে আমাদের কোন মই নেই আর তাকে না বলা উচিত। আমি তাকে প্রার্থনা করতে শিক্ষা দিই ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ مَوْضِعُ ‏ ‏مَسْجِدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏وَكَانَ فِيهِ نَخْلٌ وَخِرَبٌ وَقُبُورٌ مِنْ قُبُورِ الْجَاهِلِيَّةِ فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَامِنُونِي ‏ ‏فَقَالُوا لَا نَبْغِي بِهِ ثَمَنًا إِلَّا عِنْدَ اللَّهِ عَزَّ وَجَلَّ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّخْلِ فَقُطِعَ وَبِالْحَرْثِ فَأُفْسِدَ وَبِالْقُبُورِ ‏ ‏فَنُبِشَتْ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ ذَلِكَ ‏ ‏يُصَلِّي فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ حَيْثُ أَدْرَكَتْهُ الصَّلَاةُ ‏","","",""],[11795,11795,"","আমরা হারুনের কথা বলেছি যে আমরা হামাদ বেনকে তার পরিচয় গোপন রাখতে বলেছি। তার ঈশ্বর তার আত্মা চুরি করতে তাকে আশীর্বাদ করেছেন। তিনি বলেছিলেন, তিনি তার কাছে প্রার্থনা করবেন যেন তিনি আত্মসমর্পণ করেন। তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং বলেছিলেন, তিনি তার কাছে আত্মসমর্পণ করবেন এবং তৃতীয় জনের মধ্যে ঘুমিয়ে পড়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ جَارًا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَارِسِيًّا كَانَ طَيِّبَ الْمَرَقِ فَصَنَعَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ جَاءَهُ يَدْعُوهُ فَقَالَ وَهَذِهِ ‏ ‏لِعَائِشَةَ ‏ ‏فَقَالَ لَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ثُمَّ عَادَ يَدْعُوهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَذِهِ قَالَ لَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَذِهِ قَالَ نَعَمْ فِي الثَّالِثَةِ ‏ ‏فَقَامَا ‏ ‏يَتَدَافَعَانِ ‏ ‏حَتَّى أَتَيَا مَنْزِلَهُ ‏","","",""],[11796,11796,"","আমরা এমন লোকদের জন্য শাসক হওয়া সম্পর্কে কথা বলেছি যারা আল্লাহ্‌র কাছে আত্মসমর্পণ করেছে. পার্থক্য গড়ে তোলার জন্য প্রচেষ্টা করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَدِينَةُ ‏ ‏يَأْتِيهَا ‏ ‏الدَّجَّالُ ‏ ‏فَيَجِدُ الْمَلَائِكَةَ يَحْرُسُونَهَا فَلَا يَدْخُلُهَا ‏ ‏الدَّجَّالُ ‏ ‏وَلَا الطَّاعُونُ إِنْ شَاءَ اللَّهُ تَعَالَى ‏","","",""],[11797,11797,"","আমরা কথা বলেছি আপনি কিভাবে ভুলে গেছেন যে এটা করতে হবে। আমি আর ঘন্টা দুই আর আমি একটা কারন দ্বারা মাতাল আর আমি নিজেকেই মাতাল।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بُعِثْتُ أَنَا وَالسَّاعَةُ كَهَاتَيْنِ وَأَشَارَ بِالسَّبَّابَةِ وَالْوُسْطَى ‏","","",""],[11798,11798,"","আমরা একটা ঘোড়ার কথা বলেছি যে বলেছে খোদা এটা তার মুখের মধ্যে করেছিলেন, দৈত্যটা তোমার মায়ের মধ্যে আছে আর আমি তোমার শ্বাস নিতে পারছি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاهِدُوا الْمُشْرِكِينَ بِأَمْوَالِكُمْ وَأَنْفُسِكُمْ وَأَلْسِنَتِكُمْ ‏","","",""],[11799,11799,"","একবার মজা করার বিষয়ে আমরা কথা বলেছিলাম । তার অন্তরের অবস্থা, এটা নিজের হাতে ছিল, সে তার নিজের হাতে ছিল, যখন তুমি তাকে তার প্রার্থনা করতে দেখে... ...আর তার ভেতরে তদন্ত করতে দেখে সে তার মুখ থেকে চুরি করতো. প্রভু প্রভু কে তার পালনকর ্ তা আছে বলে তাকে বলতে দিন, আমি আমার প্রার্থনায় আছি এবং আমি আমার নিজের প্রতি ভালোবাসায় আছি। ঈশ্বর তাঁর জন্য প্রার্থনা করেন এবং তিনি তার কাছে আত্মসমর্পণ করবেন। ঈশ্বর আপনাকে স্পর্শ করতে এবং তাঁকে স্পর্শ করতে পারেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏يَؤُمُّ قَوْمَهُ فَدَخَلَ ‏ ‏حَرَامٌ ‏ ‏وَهُوَ يُرِيدُ أَنْ يَسْقِيَ نَخْلَهُ فَدَخَلَ الْمَسْجِدَ لِيُصَلِّيَ مَعَ الْقَوْمِ فَلَمَّا رَأَى ‏ ‏مُعَاذًا ‏ ‏طَوَّلَ ‏ ‏تَجَوَّزَ ‏ ‏فِي صَلَاتِهِ وَلَحِقَ بِنَخْلِهِ ‏ ‏يَسْقِيهِ فَلَمَّا قَضَى ‏ ‏مُعَاذٌ ‏ ‏الصَّلَاةَ قِيلَ لَهُ إِنَّ ‏ ‏حَرَامًا ‏ ‏دَخَلَ الْمَسْجِدَ فَلَمَّا رَآكَ طَوَّلْتَ ‏ ‏تَجَوَّزَ ‏ ‏فِي صَلَاتِهِ وَلَحِقَ بِنَخْلِهِ ‏ ‏يَسْقِيهِ قَالَ إِنَّهُ لَمُنَافِقٌ أَيَعْجَلُ عَنْ الصَّلَاةِ مِنْ أَجْلِ سَقْيِ نَخْلِهِ قَالَ فَجَاءَ ‏ ‏حَرَامٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمُعَاذٌ ‏ ‏عِنْدَهُ فَقَالَ يَا نَبِيَّ اللَّهِ إِنِّي أَرَدْتُ أَنْ أَسْقِيَ نَخْلًا لِي فَدَخَلْتُ الْمَسْجِدَ لِأُصَلِّيَ مَعَ الْقَوْمِ فَلَمَّا طَوَّلَ تَجَوَّزْتُ فِي صَلَاتِي وَلَحِقْتُ بِنَخْلِي ‏ ‏أَسْقِيهِ فَزَعَمَ أَنِّي مُنَافِقٌ فَأَقْبَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏مُعَاذٍ ‏ ‏فَقَالَ ‏ ‏أَفَتَّانٌ ‏ ‏أَنْتَ ‏ ‏أَفَتَّانٌ ‏ ‏أَنْتَ ‏ ‏لَا تُطَوِّلْ بِهِمْ اقْرَأْ ‏ ‏بِسَبِّحْ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَالشَّمْسِ وَضُحَاهَا ‏ ‏وَنَحْوِهِمَا ‏","","",""],[11800,11800,"","আমরা বাবার ছেলেকে একটি ঘোড়া খুঁজে বের করার কথা বলেছিলাম, যারা বলেছিল যে ভবিষ্যদ্বাণী ঈশ্বর এবং ঈশ্বরকে উদ্ধার করেছে। বিখ্যাত লোকেরা প্রার্থনা করেছিল যদি আপনি বিখ্যাত হতেন, তাহলে মজার মজারটা করুন। তাদের অন্তর থেকে আমি তোমাকে পছন্দ করি না... ...আমি এখনো আমার লর্ডকে মেরে ফেলেছি।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏وَاصَلَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آخِرَ الشَّهْرِ ‏ ‏وَوَاصَلَ ‏ ‏نَاسٌ مِنْ النَّاسِ فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَوْ مُدَّ لَنَا الشَّهْرُ ‏ ‏لَوَاصَلْتُ ‏ ‏وِصَالًا ‏ ‏يَدَعُ ‏ ‏الْمُتَعَمِّقُونَ ‏ ‏تَعَمُّقَهُمْ ‏ ‏إِنِّي لَسْتُ مِثْلَكُمْ إِنِّي أَظَلُّ يُطْعِمُنِي رَبِّي وَيَسْقِينِي ‏","","",""]];
